def eadric_fire_magic_akisi():
    e = eadric_adi()
    return [
        satir(
            e,
            bt(
                "Bir şey daha var. Taş değil; ateş. Elimde kalan kıvılcımı 1230 coin'e bırakırım.",
                "There is one more thing. Not stone; fire. I will part with the spark I have left for 1230 coins.",
            ),
        ),
        satir(
            e,
            bt(
                "Ucuz değildir. Ateş borç tutmaz; bedelini ya şimdi alır, ya sonra.",
                "It is not cheap. Fire keeps no debt; it takes its price now or later.",
            ),
        ),
        secim(
            [
                (
                    bt(
                        "1230 coin. Ver.",
                        "1230 coins. Give it to me.",
                    ),
                    [aksiyon("eadric_fire_magic_satinal")],
                ),
                (
                    bt("Kalsın.", "Keep it."),
                    [
                        satir(
                            e,
                            bt(
                                "Ateş beklemeyi bilir.",
                                "Fire knows how to wait.",
                            ),
                        ),
                        aksiyon("eadric_fire_magic_reddet"),
                    ],
                ),
            ]
        ),
    ]


def rastgele_eadric_akisi():
    global eadric_fire_magic_teklif_kilit_konusma
    e = eadric_adi()

    akislari = [
        [
            satir(
                karakter_konusmaci(),
                bt("Hâlâ burada mısın?", "Are you still here?"),
            ),
            satir(
                e,
                bt(
                    "Hayır. Burada kalan tarafımı bekliyorum.",
                    "No. I am waiting for the part of me that remained here.",
                ),
            ),
        ],
        [
            satir(
                karakter_konusmaci(),
                bt(
                    "Mağaranın içinde ne var?",
                    "What is inside the cave?",
                ),
            ),
            satir(
                e,
                bt(
                    "İçeri giren herkes başka bir cevap getiriyor. "
                    "Çıkan olursa sorarsın.",
                    "Everyone who enters brings a different answer. Ask one "
                    "of them, should anyone come out.",
                ),
            ),
        ],
        [
            satir(
                karakter_konusmaci(),
                bt(
                    "Taşları neden diziyorsun?",
                    "Why are you arranging the stones?",
                ),
            ),
            satir(
                e,
                bt(
                    "Dağılmasınlar diye.",
                    "So they do not scatter.",
                ),
            ),
            satir(
                karakter_konusmaci(),
                bt("Taşlar dağılmaz.", "Stones do not scatter."),
            ),
            satir(
                e,
                bt(
                    "Dün gece biriydiler.",
                    "Last night they were one.",
                ),
            ),
        ],
        [
            satir(
                karakter_konusmaci(),
                bt("Bana bir fıkra anlat.", "Tell me a joke."),
            ),
            satir(
                e,
                bt(
                    "Temel ile Dursun işte çalışırken…",
                    "While Temel and Dursun were at work…",
                ),
            ),
            satir(
                e,
                bt(
                    "Temel, “Buranın ampulü artık benim. Burayı ben "
                    "aydınlatıyorum.” demiş.",
                    "Temel said, “I am the light bulb here now. I illuminate "
                    "this place.”",
                ),
            ),
            satir(
                e,
                bt(
                    "Patron da Temel’e, “Sen git, bir tatil yap.” demiş.",
                    "The boss told Temel, “Go and take a holiday.”",
                ),
            ),
            satir(
                e,
                bt(
                    "Temel gitmiş. Dursun da çantasını topluyormuş. "
                    "Patron, “Dursun, sen niye toplanıyorsun?” demiş.",
                    "Temel left. Dursun began packing too. The boss asked, "
                    "“Dursun, why are you packing?”",
                ),
            ),
            satir(
                e,
                bt(
                    "Dursun da, “Karanlıkta mı çalışayım?” demiş.",
                    "Dursun replied, “Am I supposed to work in the dark?”",
                ),
            ),
        ],
    ]

    if not fire_magic_eadric_alindi:
        if eadric_fire_magic_teklif_kilit_konusma > 0:
            eadric_fire_magic_teklif_kilit_konusma -= 1
        else:
            olasilik = max(
                0.035,
                0.24 * (0.43 ** max(0, eadric_fire_magic_reddetme)),
            )
            if random.random() < olasilik:
                return eadric_fire_magic_akisi()
    return random.choice(akislari)
