def fire_magic_sesi_cal(tur):
    """Sphaera Exothermica'nın üç fazlı ses kontratı.

    charge   -> ilk ateş göründüğü anda (ses 1)
    whoosh   -> projectile serbest bırakıldığında (ses 2)
    explosion-> gerçek patlama karesinde (ses 3)
    """
    if not pygame.mixer.get_init():
        return
    tur = str(tur).lower().strip()
    ses = {
        "charge": fire_magic_charge_sesi,
        "whoosh": fire_magic_whoosh_sesi,
        "explosion": fire_magic_explosion_sesi,
    }.get(tur)
    if ses is None:
        return
    gain = {
        "charge": 0.82,
        "whoosh": 0.96,
        "explosion": 1.0,
    }.get(tur, 1.0)
    ses.set_volume(max(0.0, min(1.0, _efekt_ses_orani() * gain)))
    ses.play()
