ignis_sembol_resmi = (
    sembol_resmi_yukle(IGNIS_SEMBOL_YOLU) if IGNIS_SEMBOL_YOLU else None
)


def spell_okulu_sembol_ciz(okul, rect, alpha=255):
    """Okul sembolünü verilen kutuya çizer; IGNIS için kullanıcının PNG'si önceliklidir."""
    okul = str(okul or "").upper()
    if okul == "IGNIS" and ignis_sembol_resmi is not None:
        hedef = max(8, min(int(rect.width), int(rect.height)))
        key = ("spell_school_symbol_v18", okul, hedef)
        img = sprite_olcek_onbellegi.get(key)
        if img is None:
            kaynak = ignis_sembol_resmi
            oran = min(
                hedef / max(1.0, kaynak.get_width()),
                hedef / max(1.0, kaynak.get_height()),
            )
            w = max(1, int(round(kaynak.get_width() * oran)))
            h = max(1, int(round(kaynak.get_height() * oran)))

            img = pygame.transform.smoothscale(kaynak, (w, h))
            sprite_olcek_onbellegi[key] = img
        draw = img
        if alpha < 255:
            draw = img.copy()
            draw.set_alpha(max(0, min(255, int(alpha))))
        ekran.blit(draw, draw.get_rect(center=rect.center))
        return True


    sembol = SPELL_OKULLARI.get(okul, {}).get("symbol", "")
    if sembol:
        yazi_yaz(
            sembol,
            rect.centerx,
            rect.centery,
            (255, 196, 104),
            mini_font,
            True,
        )
        return True
    return False
# </POTBO_STAGE S0282>

