    global eadric_tasi_alindi
    global eadric_tutumu
    global \
        fire_magic_eadric_alindi, \
        eadric_fire_magic_reddetme, \
        eadric_fire_magic_teklif_kilit_konusma
    global tarkard_adi_ogrenildi
    global tarkard_konusuldu
    global torrmund_konusuldu
    global oyuncu_baygin_bitis, oyuncu_zorlanmis_hiz, oyuncu_zorlanmis_bitis
    global oyuncu_kesik_efekti_bitis, oyuncu_son_infaz_kaynagi
    global oyuncu_zorlanmis_son_guncelleme, oyuncu_agir_darbe_bagisiklik_bitis
    global merchant_yukseltmeler
    global aktif_gorevler
    global onemli_item_gorulenler
    global merchant_geri_alim_listesi
    global merchant_gorulen_urunler
    global dunya_durumu, dunya_olay_gunlugu
    global dunya_son_guncelleme, dunya_onceki_konum, dunya_son_combat_zamani

    global aktif_kayit

    try:
        with open(dosya_yolu, "r", encoding="utf-8") as dosya:
            veri = json.load(dosya)

        if not gore_koru:
            kan_gore_dunyasini_temizle()
        oyuncu_olum_sahnesini_sifirla()

        oyuncu_adi = veri.get("player_name", "PLAYER")

        yuklenen_cinsiyet = veri.get("gender", "male")
        karakter_cinsiyet = (
            yuklenen_cinsiyet if yuklenen_cinsiyet in ("male", "female") else "male"
        )

        oyuncu_level = max(1, min(MAKSIMUM_LEVEL, int(veri.get("level", 1))))

        oyuncu_altin = veri.get("gold", 23)

        oyuncu_guc = veri.get("strength", 5)

        oyuncu_hasari = veri.get("damage", 10)

        oyuncu_hp = veri.get("hp", 100)

        oyuncu_max_hp = veri.get("max_hp", 100)

        oyuncu_mana = veri.get("mana", 50)

        oyuncu_max_mana = veri.get("max_mana", 50)
        oyuncu_stamina = float(veri.get("stamina", 100))
        oyuncu_max_stamina = float(veri.get("max_stamina", 100))

        if (
            int(veri.get("level_balance_version", 0) or 0) < LEVEL_BALANCE_VERSION
            and oyuncu_level > 1
        ):
            oyuncu_seviye_kazanclarini_uygula(1, oyuncu_level)
        stamina_gorunen = oyuncu_stamina
        mana_gorunen = float(oyuncu_mana)
        hp_gorunen = float(oyuncu_hp)

        yuklenen_envanter = veri.get("inventory", [None] * 30)

        if not isinstance(yuklenen_envanter, list):
            yuklenen_envanter = [None] * 30

        envanter_itemleri = (yuklenen_envanter[:30] + [None] * 30)[:30]


        for _i, _item in enumerate(envanter_itemleri):
            if isinstance(_item, dict):
                if _item.get("id") == "health_potion":
                    envanter_itemleri[_i] = None
                    continue
                try:
                    _item["quantity"] = max(
                        1,
                        min(10, int(_item.get("quantity", 1))),
                    )
                except (TypeError, ValueError):
                    _item["quantity"] = 1

        yuklenen_one_cikanlar = veri.get("featured_slots", [0, 1, 2, 3, 4])

        if not isinstance(yuklenen_one_cikanlar, list):
            yuklenen_one_cikanlar = [0, 1, 2, 3, 4]

        one_cikan_slotlar = []

        for index in range(5):
            try:
                ham_slot = yuklenen_one_cikanlar[index]
            except IndexError:
                ham_slot = index

            if ham_slot is None:
                slot_index = None
            else:
                try:
                    slot_index = max(0, min(29, int(ham_slot)))
                except (TypeError, ValueError):
                    slot_index = index

            one_cikan_slotlar.append(slot_index)

        envanter_secili_slot = max(0, min(4, int(veri.get("featured_selected", 0))))

        secili_one_cikan_index = one_cikan_slotlar[envanter_secili_slot]
        envanter_imlec = (
            secili_one_cikan_index if isinstance(secili_one_cikan_index, int) else 0
        )

        ham_q = veri.get("q_quick_slot", None)
        try:
            q_hizli_item_index = int(ham_q) if ham_q is not None else None
        except (TypeError, ValueError):
            q_hizli_item_index = None
        q_hizli_slot_normalize_et()

        eadric_adi_ogrenildi = bool(veri.get("eadric_name_known", False))
        npc_intro_tamamlandi = bool(veri.get("npc_intro_done", False))
        ganimet_alindi = bool(veri.get("loot_taken", False))
        ganimet_asamasi = max(
            0,
            min(
                3,
                int(veri.get("loot_stage", 3 if ganimet_alindi else 0)),
            ),
        )
        if ganimet_asamasi >= 3:
            ganimet_alindi = True
        ganimet_sonrasi_konusma_yapildi = bool(veri.get("post_loot_done", False))
        magara_yolu_ogrenildi = bool(
            veri.get(
                "cave_route_known",
                veri.get("cave_unlocked", False),
            )
        )
        eadric_tasi_alindi = bool(veri.get("eadric_stone_taken", False))
        eadric_tutumu = str(veri.get("eadric_attitude", "neutral"))
        fire_magic_eadric_alindi = bool(veri.get("fire_magic_from_eadric", False))
        eadric_fire_magic_reddetme = max(0, int(veri.get("eadric_fire_declines", 0)))
        eadric_fire_magic_teklif_kilit_konusma = max(
            0, int(veri.get("eadric_fire_offer_lock", 0))
        )
        tarkard_adi_ogrenildi = bool(veri.get("tarkard_name_known", False))
        tarkard_konusuldu = bool(veri.get("tarkard_spoken", False))
        torrmund_konusuldu = bool(veri.get("torrmund_spoken", False))

        yuklenen_yukseltmeler = veri.get("merchant_upgrades", {})
        if isinstance(yuklenen_yukseltmeler, dict):
            merchant_yukseltmeler = {
                "weapon": max(
                    1,
                    int(yuklenen_yukseltmeler.get("weapon", 1)),
                ),
                "armor": max(
                    1,
                    int(yuklenen_yukseltmeler.get("armor", 1)),
                ),
                "focus": max(
                    1,
                    int(yuklenen_yukseltmeler.get("focus", 1)),
                ),
            }
        else:
            merchant_yukseltmeler = {
                "weapon": 1,
                "armor": 1,
                "focus": 1,
            }

        yuklenen_gorevler = veri.get("quests", {})
        aktif_gorevler = (
            yuklenen_gorevler if isinstance(yuklenen_gorevler, dict) else {}
        )

        gorulen = veri.get("important_items_seen", [])
        onemli_item_gorulenler = (
            set(str(x) for x in gorulen) if isinstance(gorulen, list) else set()
        )

        geri_alim = veri.get("merchant_buyback", [])
        merchant_geri_alim_listesi = geri_alim if isinstance(geri_alim, list) else []



        if not fire_magic_eadric_alindi:
            inventory_has = any(
                isinstance(it, dict) and it.get("id") == "fire_magic"
                for it in envanter_itemleri
            )
            buyback_has = any(
                isinstance(it, dict) and it.get("id") == "fire_magic"
                for it in merchant_geri_alim_listesi
            )
            fire_magic_eadric_alindi = inventory_has or buyback_has

        gorulen_urunler = veri.get("merchant_products_seen", [])
        merchant_gorulen_urunler = (
            set(str(x) for x in gorulen_urunler)
            if isinstance(gorulen_urunler, list)
            else set()
        )

        dunya_durumu = varsayilan_dunya_durumu()
        yuklenen_dunya = veri.get("world_state", {})
        if isinstance(yuklenen_dunya, dict):
            for anahtar in dunya_durumu:
                if anahtar in yuklenen_dunya:
                    dunya_durumu[anahtar] = yuklenen_dunya[anahtar]
        try:
            dunya_durumu["version"] = max(1, int(dunya_durumu.get("version", 2)))
            dunya_durumu["elapsed_ms"] = max(0, int(dunya_durumu.get("elapsed_ms", 0)))
            dunya_durumu["distance_travelled"] = max(
                0.0,
                float(dunya_durumu.get("distance_travelled", 0.0)),
            )
            dunya_durumu["tension"] = max(
                0.0,
                min(1.0, float(dunya_durumu.get("tension", 0.0))),
            )
            dunya_durumu["threat"] = max(
                0.0,
                min(1.0, float(dunya_durumu.get("threat", 0.0))),
            )
            for sayac in (
                "items_acquired",
                "items_used",
                "items_dropped",
                "merchant_buys",
                "merchant_sells",
                "combat_hits_given",
                "combat_hits_taken",
                "saves",
                "event_seq",
            ):
                dunya_durumu[sayac] = max(0, int(dunya_durumu.get(sayac, 0)))
        except (TypeError, ValueError):
            dunya_durumu = varsayilan_dunya_durumu()

        yuklenen_olaylar = veri.get("world_event_log", [])
        dunya_olay_gunlugu = deque(
            [x for x in yuklenen_olaylar[-72:] if isinstance(x, dict)]
            if isinstance(yuklenen_olaylar, list)
            else [],
            maxlen=72,
        )

        oyuncu_x = float(veri.get("x", 620))

        oyuncu_y = float(veri.get("y", 600))

        common_enemy_durumunu_yukle(veri.get("common_enemies"))
        tarkard_durumunu_yukle(veri.get("tarkard"))
        torrmund_durumunu_yukle(veri.get("torrmund"))
        fire_magic_transient_sifirla()


        oyuncu_baygin_bitis = 0
        oyuncu_zorlanmis_hiz = pygame.Vector2(0.0, 0.0)
        oyuncu_zorlanmis_bitis = 0
        oyuncu_zorlanmis_son_guncelleme = pygame.time.get_ticks()
        oyuncu_agir_darbe_bagisiklik_bitis = 0
        oyuncu_kesik_efekti_bitis = 0
        oyuncu_son_infaz_kaynagi = ""
        oyuncu_saldiri_durumunu_sifirla()
        oyuncu_locomotion_durumunu_sifirla()

        aktif_kayit = dosya_yolu
        envanter_tasima_kaynagi = None
        one_cikan_tasima_kaynagi = None
        one_cikan_atama_item_index = None
        envanter_aksiyon_kaynagi = "grid"
        onemli_item_kuyrugu = []
        onemli_item_gosterim_aktif = False
        onemli_item_gosterim_hazir_zamani = 0
        onemli_item_gorsel_hazir_zamani = 0
        one_cikan_slotlarini_normalize_et()
        dunya_son_guncelleme = pygame.time.get_ticks()
        dunya_onceki_konum = (oyuncu_x, oyuncu_y)
        dunya_son_combat_zamani = -10000

        return True

    except (
        FileNotFoundError,
        json.JSONDecodeError,
        OSError,
        TypeError,
        ValueError,
    ):
        return False
