def item_aciklamasi(index):
    if not 0 <= index < len(envanter_itemleri):
        return {
            "name": "",
            "category": "",
            "type": "",
            "description": "",
        }

    item = envanter_itemleri[index]

    if not isinstance(item, dict):
        return {
            "name": "",
            "category": "",
            "type": "",
            "description": "",
        }

    item_id = item.get("id")

    if item_id == "aurum_potabile":
        yerel = aurum_potabile_olustur()
    elif item_id == "quinta_essentia":
        yerel = quinta_essentia_olustur()
    elif item_id == "eadric_stone":
        yerel = eadric_tasi_olustur()
    elif item_id == "health_potion":
        yerel = can_iksiri_olustur()
    elif item_id == "fire_magic":
        yerel = fire_magic_olustur()
    elif item_id == "corona_aetherica":
        yerel = corona_aetherica_olustur()
    else:
        yerel = dict(item)


    sonuc = dict(item)
    sonuc.update(yerel)

    return sonuc
# </POTBO_STAGE S0343>

