def fire_magic_olustur():
    kategori = bt("BÜYÜ", "SPELL")
    return {
        "id": "fire_magic",
        "name": "Sphaera Exothermica",
        "category": kategori,
        "type": kategori,
        "important": True,
        "spell": True,
        "q_only": True,
        "infinite": True,
        "spell_school": "IGNIS",
        "spell_symbol": SPELL_OKULLARI["IGNIS"]["symbol"],
        "description": bt(
            "İnce dağılmış yanıcı cevherin, havanın oksitleyici unsuruyla ani ve denetimli bir tepkimeye sokulmasıyla oluşturulan küresel bir yanma biçimidir. Simyacılar, açığa çıkan ısının cevherin çevresinde tutulması hâlinde tepkimenin dağılmadan ilerleyebileceğini ve taşıdığı yanıcı madde tükenene kadar ateşini koruyabileceğini düşünürler.",
            "A spherical form of combustion created by bringing finely dispersed combustible ore into a sudden, controlled reaction with the oxidizing constituent of air. Alchemists hold that if the released heat is confined around the ore, the reaction can advance without dispersing and preserve its fire until the carried combustible matter is exhausted.",
        ),
    }


