def one_cikan_slotlarini_normalize_et():
    """Geçersiz ve yinelenen featured referanslarını tekilleştirir."""
    gorulen = set()
    for slot_index, item_index in enumerate(one_cikan_slotlar):
        gecerli = (
            isinstance(item_index, int)
            and 0 <= item_index < len(envanter_itemleri)
            and isinstance(envanter_itemleri[item_index], dict)
            and not bool(
                envanter_itemleri[item_index].get("spell", False)
                or envanter_itemleri[item_index].get("id") == "fire_magic"
            )
            and item_index not in gorulen
        )
        if not gecerli:
            one_cikan_slotlar[slot_index] = None
            continue
        gorulen.add(item_index)
