def item_buyu_mu(item):
    return isinstance(item, dict) and bool(
        item.get("spell", False) or item.get("id") == "fire_magic"
    )


def item_q_hizli_kullanima_uygun_mu(item):
    if not isinstance(item, dict):
        return False
    return item.get("id") in (
        "health_potion",
        "aurum_potabile",
        "quinta_essentia",
        "fire_magic",
        "corona_aetherica",
    )
