def q_hizli_itemi_kullan():


    if gelistirici_sonsuz_ates:
        return fire_magic_kullan()
    q_hizli_slot_normalize_et()
    if q_hizli_item_index is None:
        bildirim_goster(bt("Q hızlı slotu boş.", "Q quick slot is empty."))
        return False
    item = envanter_itemleri[q_hizli_item_index]
    if not isinstance(item, dict):
        return False
    if item_buyu_mu(item):


        if item.get("id") == "fire_magic":
            return fire_magic_kullan()
        if item.get("id") == "corona_aetherica":
            bildirim_goster(
                bt(
                    "Corona Aetherica envanter tanımı ve görseli eklendi; savaş mekaniği henüz bağlanmadı.",
                    "Corona Aetherica has its inventory entry and art wired in; its combat mechanic is not bound yet.",
                )
            )
            return False
        return False
    secili_itemi_kullan(q_hizli_item_index)
    q_hizli_slot_normalize_et()
    return True
