def _stage1__kan_profil_degerleri(profil, lethal=False):


    tablo = {
        "burn": (4, 1, 0.62),
        "light_slash": (10, 2, 0.82),
        "slash": (15, 3, 1.00),
        "medium_blunt": (19, 3, 1.12),
        "medium_slash": (24, 4, 1.24),
        "magic_heavy": (30, 6, 1.42),
        "heavy_blunt": (39, 7, 1.60),
        "heavy_slash": (48, 9, 1.82),
    }
    parcacik, leke, guc = tablo.get(str(profil), tablo["slash"])
    if lethal:
        parcacik = int(parcacik * 2.10) + 10
        leke += 5
    return parcacik, leke, guc
