# <POTBO_STAGE S0409>


def _stage1_gore_olum_patlamasi(x, y, profil="slash", yon=None):
    """Lethal fiziksel darbeyi ağırlığına göre anatomik parçalanmaya çevirir.

    V27'de ağır kesik yalnız daha çok sprite üretmez: parçalar kesik doğrultusunda
    ortak momentum taşır. Bu, vuruşu konfeti gibi radyal değil, bıçağın kütlesiyle
    bedenin içinden geçmiş gibi okutur.
    """
    heavy = profil in (
        "heavy_blunt",
        "heavy_slash",
        "magic_heavy",
    )
    medium = profil in ("medium_blunt", "medium_slash")
    if heavy:
        adet = random.randint(14, 20)
        guc = 1.52 if profil == "heavy_slash" else 1.32
    elif medium:
        adet = random.randint(8, 12)
        guc = 1.06
    else:
        adet = random.randint(4, 6)
        guc = 0.80

    kinds = list(GORE_SPRITELERI.keys()) or [
        "liver",
        "intestine",
    ]
    if heavy:

        agir_havuz = [
            "intestine",
            "liver",
            "organ_mass_a",
            "organ_mass_b",
            "organ_round_a",
            "organ_round_b",
            "flesh_shard_a",
            "flesh_shard_b",
            "intestine",
            "liver",
            "leg",
            "foot",
            "ribcage",
            "spinal_cord",
            "skull",
            "bone_long_a",
            "bone_long_b",
            "bone_cluster_a",
            "bone_cluster_b",
            "intestine",
            "liver",
            "flesh_shard_a",
        ]
        secimler = [k for k in agir_havuz if k in kinds] or kinds
    elif medium:
        orta_havuz = [
            "intestine",
            "liver",
            "organ_round_a",
            "organ_round_b",
            "flesh_shard_a",
            "flesh_shard_b",
            "leg",
            "foot",
            "bone_long_a",
            "bone_cluster_a",
            "spinal_cord",
            "skull",
        ]
        secimler = [k for k in orta_havuz if k in kinds] or kinds
    else:
        secimler = kinds

    ana = pygame.Vector2(yon) if yon is not None else pygame.Vector2(0.0, 0.0)
    if ana.length_squared() > 1e-6:
        ana = ana.normalize()

    for i in range(adet):
        kind = (
            secimler[i % len(secimler)]
            if i < len(secimler)
            else random.choice(secimler)
        )
        small = (i >= max(5, adet // 2)) or (
            random.random() < (0.28 if heavy else 0.18)
        )
        parca = GoreChunk(kind, x, y, guc=guc, small=small)

        if profil == "heavy_slash" and ana.length_squared() > 0.0:

            d = ana.rotate(random.uniform(-52.0, 52.0))
            if random.random() < 0.16:
                d *= -1.0
            if d.length_squared() > 1e-6:
                d = d.normalize()
            parca.v = d * random.uniform(185.0, 345.0) * (0.82 if small else 1.0)
            parca.vz = random.uniform(165.0, 315.0)
            parca.angular = random.uniform(-540.0, 540.0)
        elif profil == "heavy_blunt":
            parca.v *= random.uniform(1.18, 1.55)
            parca.vz *= random.uniform(1.05, 1.30)
        gore_chunks.append(parca)
