def fire_magic_transient_sifirla():
    """
    Büyüye ait sahne-geçici state'i tek noktadan temizler.

    Save/load veya yeni oyun sırasında eski projectile, explosion, burn ve zemin
    alevinin yeni sahneye sızmasını önler. Fire Magic envanterde kalıcı olabilir;
    burada yalnız transient fizik sıfırlanır.
    """
    global fire_magic_cast_fx, fire_magic_cast_lock_until, fire_magic_son_kullanim
    global player_magic_projectiles, player_magic_explosions, player_magic_ground_fires
    global fire_ground_touch_cooldowns
    global \
        fire_magic_screen_flash_until, \
        fire_magic_screen_flash_started, \
        combat_impact_fx
    global oyuncu_fire_burn_until, oyuncu_fire_burn_next_tick
    global oyuncu_fire_burn_tick_damage, oyuncu_fire_burn_source

    fire_magic_cast_fx = None
    fire_magic_cast_lock_until = 0
    fire_magic_son_kullanim = -10000
    player_magic_projectiles = []
    player_magic_explosions = []
    player_magic_ground_fires = []
    fire_ground_touch_cooldowns = {}
    fire_magic_screen_flash_until = 0
    fire_magic_screen_flash_started = 0
    combat_impact_fx = []

    oyuncu_fire_burn_until = 0
    oyuncu_fire_burn_next_tick = 0
    oyuncu_fire_burn_tick_damage = 0
    oyuncu_fire_burn_source = ""



    for _dusman in list(common_enemies) + [
        d for d in (tarkard_actor, torrmund_actor) if d is not None
    ]:
        for _ad, _deger in (
            ("fire_burn_until", 0),
            ("fire_burn_next_tick", 0),
            ("fire_burn_damage_remaining", 0),
            ("fire_burn_ticks_remaining", 0),
            ("fire_impulse_until", 0),
        ):
            try:
                setattr(_dusman, _ad, _deger)
            except Exception:
                pass
        try:
            _dusman.fire_impulse_v = pygame.Vector2(0.0, 0.0)
        except Exception:
            pass
