def _magic_hedef_yaricapi(dusman):
    tur = getattr(dusman, "tur", "")
    if tur == "torrmund":
        return 34.0
    if tur == "tarkard":
        return 32.0
    if tur == "berserker":
        return 25.0
    if tur == "crawler":
        return 22.0
    if tur == "headsthrower":
        return 18.0
    return 22.0


def _fire_magic_band_sec(etkin_mesafe):
    """İstenen dört sabit hasar kabuğunu seçer."""
    d = max(0.0, float(etkin_mesafe))
    for yaricap, hasar in FIRE_MAGIC_EXPLOSION_BANDS:
        if d <= float(yaricap):
            return int(hasar), float(yaricap)
    return 0, float(FIRE_MAGIC_EXPLOSION_RADIUS)


def _fire_magic_burn_total(hasar):
    if not gelistirici_yanma_efekti_aktif:
        return 0
    return int(FIRE_MAGIC_BURN_TOTAL_BY_BAND.get(int(hasar), 0))


def _v30_fire_magic_hasar_roll(
    shell_id,
    etkin_mesafe,
    shell_radius,
    momentum_dir,
    radial_dir,
    seed,
):
    """Aynı shell içinde 6 HP'lik küçük fiziksel varyans üretir.

    %55 shell içindeki konum, %25 projectile momentumuyla hizalanma, %20 mikro impact
    varyansı. Böylece değerler rastgele zıplamaz ama 672/678 gibi tek sayıya da kilitlenmez.
    """
    low, high = FIRE_MAGIC_EXPLOSION_DAMAGE_RANGES.get(
        int(shell_id), (int(shell_id), int(shell_id))
    )
    onceki_radius = 0.0
    for rr, sid in FIRE_MAGIC_EXPLOSION_BANDS:
        if int(sid) == int(shell_id):
            break
        onceki_radius = float(rr)
    kalinlik = max(1.0, float(shell_radius) - onceki_radius)
    local_p = max(
        0.0,
        min(
            1.0,
            (float(etkin_mesafe) - onceki_radius) / kalinlik,
        ),
    )
    proximity = 1.0 - local_p

    md = pygame.Vector2(momentum_dir or (0.0, 0.0))
    rd = pygame.Vector2(radial_dir or (0.0, 0.0))
    if md.length_squared() > 1e-8 and rd.length_squared() > 1e-8:
        momentum = 0.5 + 0.5 * max(-1.0, min(1.0, md.normalize().dot(rd.normalize())))
    else:
        momentum = 0.5
    rng = random.Random(int(seed) ^ (int(shell_id) * 7919))
    mikro = rng.random()
    kalite = max(
        0.0,
        min(
            1.0,
            proximity * 0.55 + momentum * 0.25 + mikro * 0.20,
        ),
    )
    return int(low + round((high - low) * kalite))


class _V30FireDamageSource:
    def __init__(self, x, y, profile):
        self.x = float(x)
        self.y = float(y)
        self.tur = "fire_magic_explosion"
        self.damage_profile = str(profile)
        self.is_player_magic = True


def fire_magic_yanma_durumlarini_temizle():
    """Burn debug kapatıldığında mevcut 6 saniyelik DoT'ları atomik temizler.

    Burn/DoT katmanı normal oyun davranışını korur; ayrı geliştirici toggle'ı yoktur.
    """
    global oyuncu_fire_burn_until, oyuncu_fire_burn_next_tick
    global oyuncu_fire_burn_tick_damage, oyuncu_fire_burn_source
    oyuncu_fire_burn_until = 0
    oyuncu_fire_burn_next_tick = 0
    oyuncu_fire_burn_tick_damage = 0
    oyuncu_fire_burn_source = ""
    for dusman in list(common_enemies) + [
        d for d in (tarkard_actor, torrmund_actor) if d is not None
    ]:
        for ad, deger in (
            ("fire_burn_until", 0),
            ("fire_burn_next_tick", 0),
            ("fire_burn_damage_remaining", 0),
            ("fire_burn_ticks_remaining", 0),
        ):
            try:
                setattr(dusman, ad, deger)
            except Exception:
                pass


def _fire_magic_burn_enemy_uygula(dusman, toplam_hasar, simdi):
    if not gelistirici_yanma_efekti_aktif:
        return
    if (
        dusman is None
        or not getattr(dusman, "active", False)
        or getattr(dusman, "hp", 0) <= 0
    ):
        return
    toplam = max(0, int(toplam_hasar))
    if toplam <= 0:
        return

    tick_sayisi = max(
        1,
        FIRE_MAGIC_BURN_DURATION_MS // FIRE_MAGIC_BURN_TICK_MS,
    )
    mevcut_kalan = max(0, int(getattr(dusman, "fire_burn_damage_remaining", 0)))
    mevcut_tick = max(0, int(getattr(dusman, "fire_burn_ticks_remaining", 0)))




    if mevcut_kalan > toplam and mevcut_tick > 0:
        toplam = mevcut_kalan
        tick_sayisi = max(tick_sayisi, mevcut_tick)

    dusman.fire_burn_until = int(simdi) + FIRE_MAGIC_BURN_DURATION_MS
    dusman.fire_burn_next_tick = int(simdi) + FIRE_MAGIC_BURN_TICK_MS
    dusman.fire_burn_damage_remaining = int(toplam)
    dusman.fire_burn_ticks_remaining = int(tick_sayisi)


def _fire_magic_burn_player_uygula(toplam_hasar, simdi):
    global oyuncu_fire_burn_until
    if not gelistirici_yanma_efekti_aktif:
        return
    global oyuncu_fire_burn_next_tick
    global oyuncu_fire_burn_tick_damage, oyuncu_fire_burn_source

    if oyuncu_hp <= 0:
        return
    toplam = max(0, int(toplam_hasar))
    if toplam <= 0:
        return

    tick_sayisi = max(
        1,
        FIRE_MAGIC_BURN_DURATION_MS // FIRE_MAGIC_BURN_TICK_MS,
    )


    oyuncu_fire_burn_tick_damage = max(
        int(oyuncu_fire_burn_tick_damage),
        int(math.ceil(toplam / float(tick_sayisi))),
    )
    oyuncu_fire_burn_until = int(simdi) + FIRE_MAGIC_BURN_DURATION_MS
    oyuncu_fire_burn_next_tick = int(simdi) + FIRE_MAGIC_BURN_TICK_MS
    oyuncu_fire_burn_source = "fire_magic"


def _fire_magic_enemy_impulse_uygula(dusman, merkez, hiz, simdi):
    if dusman is None or not getattr(dusman, "active", False):
        return
    merkez = pygame.Vector2(merkez)
    pos = pygame.Vector2(float(dusman.x), float(dusman.y))
    yon = pos - merkez
    if yon.length_squared() <= 1e-6:

        seed = sum(ord(c) for c in str(getattr(dusman, "uid", "enemy")))
        angle = math.radians(seed % 360)
        yon = pygame.Vector2(math.cos(angle), math.sin(angle))
    else:
        yon = yon.normalize()

    eski = getattr(dusman, "fire_impulse_v", pygame.Vector2(0.0, 0.0))
    if not isinstance(eski, pygame.Vector2):
        eski = pygame.Vector2(eski)
    yeni = eski * 0.35 + yon * float(hiz)
    yeni = _vektor_uzunluk_sinirla(yeni, max(float(hiz), 780.0))
    dusman.fire_impulse_v = yeni
    dusman.fire_impulse_until = max(
        int(getattr(dusman, "fire_impulse_until", 0)),
        int(simdi) + FIRE_MAGIC_KNOCKBACK_MS,
    )





def _fire_magic_player_impulse_uygula(merkez, hiz, simdi):
    global oyuncu_zorlanmis_hiz, oyuncu_zorlanmis_bitis
    global oyuncu_zorlanmis_son_guncelleme

    pos = pygame.Vector2(float(oyuncu_x), float(oyuncu_y))
    yon = pos - pygame.Vector2(merkez)
    if yon.length_squared() <= 1e-6:
        yon = -_yon_vektoru(oyuncu_yonu)
        if yon.length_squared() <= 1e-6:
            yon = pygame.Vector2(1.0, 0.0)
    yon = yon.normalize()

    mevcut = pygame.Vector2(oyuncu_zorlanmis_hiz)
    aday = mevcut * 0.30 + yon * float(hiz)
    oyuncu_zorlanmis_hiz = _vektor_uzunluk_sinirla(aday, max(760.0, float(hiz)))
    oyuncu_zorlanmis_bitis = max(
        int(oyuncu_zorlanmis_bitis),
        int(simdi) + FIRE_MAGIC_KNOCKBACK_MS,
    )
    oyuncu_zorlanmis_son_guncelleme = int(simdi)


def fire_magic_player_status_guncelle(simdi):
    """
    Self-hit sonrası oyuncu burn tick'leri.

    Frame-rate bağımsızdır: oyun kısa süre hitch yese bile `while` ile kaçan tickler
    telafi edilir; fakat bir frame'de sınırsız tick loop'u oluşmaması için kalan süre
    doğal olarak 6 saniye ile sınırlıdır.
    """
    global oyuncu_hp
    global oyuncu_fire_burn_until, oyuncu_fire_burn_next_tick
    global oyuncu_fire_burn_tick_damage, oyuncu_fire_burn_source

    if not gelistirici_yanma_efekti_aktif:
        if oyuncu_fire_burn_until > 0 or oyuncu_fire_burn_tick_damage > 0:
            fire_magic_yanma_durumlarini_temizle()
        return
    if oyuncu_fire_burn_until <= 0:
        return
    if oyuncu_hp <= 0:
        oyuncu_fire_burn_until = 0
        oyuncu_fire_burn_tick_damage = 0
        return

    while (
        oyuncu_fire_burn_next_tick > 0
        and simdi >= oyuncu_fire_burn_next_tick
        and oyuncu_fire_burn_next_tick <= oyuncu_fire_burn_until
        and oyuncu_hp > 0
    ):
        hasar = min(
            max(1, int(oyuncu_fire_burn_tick_damage)),
            int(oyuncu_hp),
        )
        oyuncu_hp = max(0, int(oyuncu_hp) - hasar)
        oyuncu_kanli_hasar_kaydi(oyuncu_x, oyuncu_y, "burn", hasar, "fire_magic_burn")
        dunya_olayi_kaydet(
            "hit_taken",
            damage=hasar,
            count=1,
            enemy="fire_magic_burn",
            self_hit=True,
        )
        oyuncu_fire_burn_next_tick += FIRE_MAGIC_BURN_TICK_MS

    if simdi >= oyuncu_fire_burn_until or oyuncu_hp <= 0:
        oyuncu_fire_burn_until = 0
        oyuncu_fire_burn_next_tick = 0
        oyuncu_fire_burn_tick_damage = 0
        oyuncu_fire_burn_source = ""


def fire_magic_enemy_status_preupdate(dusman, dt, simdi, digerler):
    """
    Enemy burn + explosion impulse resolver.

    Dönen True, bu frame normal AI locomotion'ın atlanması gerektiğini söyler.
    Böylece blast velocity ile AI steering aynı frame birbirini iptal etmez.
    """
    if (
        dusman is None
        or not getattr(dusman, "active", False)
        or getattr(dusman, "hp", 0) <= 0
    ):
        return False

    if not gelistirici_yanma_efekti_aktif:
        setattr(dusman, "fire_burn_until", 0)
        setattr(dusman, "fire_burn_next_tick", 0)
        setattr(dusman, "fire_burn_damage_remaining", 0)
        setattr(dusman, "fire_burn_ticks_remaining", 0)

    burn_until = int(getattr(dusman, "fire_burn_until", 0))
    next_tick = int(getattr(dusman, "fire_burn_next_tick", 0))
    while (
        burn_until > 0
        and next_tick > 0
        and simdi >= next_tick
        and next_tick <= burn_until
        and getattr(dusman, "active", False)
        and getattr(dusman, "hp", 0) > 0
    ):
        remaining = max(
            0,
            int(getattr(dusman, "fire_burn_damage_remaining", 0)),
        )
        ticks = max(
            1,
            int(getattr(dusman, "fire_burn_ticks_remaining", 1)),
        )
        tick_damage = max(1, int(math.ceil(remaining / float(ticks))))
        tick_damage = min(tick_damage, max(0, int(getattr(dusman, "hp", 0))))
        if tick_damage > 0:
            dusman.hasar_al(tick_damage)
        remaining = max(0, remaining - tick_damage)
        ticks = max(0, ticks - 1)
        setattr(dusman, "fire_burn_damage_remaining", remaining)
        setattr(dusman, "fire_burn_ticks_remaining", ticks)
        next_tick += FIRE_MAGIC_BURN_TICK_MS
        setattr(dusman, "fire_burn_next_tick", next_tick)
        if not getattr(dusman, "active", False) or getattr(dusman, "hp", 0) <= 0:
            return True

    if burn_until > 0 and simdi >= burn_until:
        setattr(dusman, "fire_burn_until", 0)
        setattr(dusman, "fire_burn_next_tick", 0)
        setattr(dusman, "fire_burn_damage_remaining", 0)
        setattr(dusman, "fire_burn_ticks_remaining", 0)

    impulse_until = int(getattr(dusman, "fire_impulse_until", 0))
    impulse = getattr(dusman, "fire_impulse_v", pygame.Vector2(0.0, 0.0))
    if not isinstance(impulse, pygame.Vector2):
        impulse = pygame.Vector2(impulse)

    if simdi < impulse_until and impulse.length_squared() > 9.0:

        step = impulse * max(0.0, float(dt))
        hedef = pygame.Vector2(dusman.x, dusman.y) + impulse * 0.12
        moved = dusman._hareketi_uygula(step.x, step.y, digerler, hedef)
        if not moved:



            impulse *= 0.16
        else:
            impulse *= math.exp(-5.4 * max(0.0, float(dt)))

        dusman.fire_impulse_v = impulse
        dusman.vx = impulse.x
        dusman.vy = impulse.y
        try:
            dusman._yonleri_hareketten_guncelle(impulse)
        except Exception:
            pass
        return True

    if impulse_until > 0:
        dusman.fire_impulse_until = 0
        dusman.fire_impulse_v = pygame.Vector2(0.0, 0.0)
    return False


def _fire_magic_flash_renk(simdi):
    """
    Burn sırasında kırmızı -> turuncu -> beyaz puls.

    Tamamen periodik üç-state yerine iki sinüsün faz farkı kullanılır; tekrar
    hissini azaltır fakat hesap maliyeti sabittir.
    """
    t = float(simdi) * 0.018
    a = 0.5 + 0.5 * math.sin(t)
    b = 0.5 + 0.5 * math.sin(t * 1.73 + 1.1)
    if b > 0.78:
        return (255, 245, 205), 150
    if a > 0.45:
        return (255, 104, 12), 135
    return (225, 24, 18), 120


def _fire_magic_burn_flames_ciz(rect, seed, simdi):
    """Ground-fire atlasından iki küçük gerçek alevi gövdeye bağlar; halo/rect yoktur."""
    if rect is None or not FIRE_MAGIC_GROUND_SPRITELERI:
        return
    frames = FIRE_MAGIC_GROUND_SPRITELERI
    for i, (rx, ry, scale_mul) in enumerate(((0.34, 0.70, 0.30), (0.66, 0.84, 0.25))):
        idx = (int(simdi // 115) + int(seed) * 3 + i * 5) % len(frames)
        frame = frames[idx]
        h = max(7, int(round(rect.height * scale_mul)))
        key = ("burn_flame_v15", id(frame), h, i)
        img = sprite_olcek_onbellegi.get(key)
        if img is None:
            sc = h / max(1.0, float(frame.get_height()))
            img = pygame.transform.scale(
                frame,
                (max(1, int(round(frame.get_width() * sc))), h),
            )
            if i == 1:
                img = pygame.transform.flip(img, True, False)
            sprite_olcek_onbellegi[key] = img
        alpha = int(178 + 52 * (0.5 + 0.5 * math.sin(simdi * 0.021 + i * 1.7)))
        draw = img.copy()
        draw.set_alpha(max(0, min(230, alpha)))
        x = rect.left + int(rect.width * rx)
        y = rect.top + int(rect.height * ry)
        ekran.blit(draw, draw.get_rect(midbottom=(x, y)))


def fire_magic_burn_overlay_sprite_ciz(aktor, sprite, rect):
    if (
        not gelistirici_yanma_efekti_aktif
        or aktor is None
        or sprite is None
        or rect is None
    ):
        return
    simdi = pygame.time.get_ticks()
    if simdi >= int(getattr(aktor, "fire_burn_until", 0)):
        return
    renk, alfa = _fire_magic_flash_renk(simdi)
    sprite_maskeli_parlama_ciz(sprite, rect, renk, int(alfa * 0.46))
    seed = sum(ord(c) for c in str(getattr(aktor, "uid", "burn"))) % 997
    _fire_magic_burn_flames_ciz(rect, seed, simdi)


def fire_magic_burn_overlay_oyuncu_ciz(sprite, rect):
    if not gelistirici_yanma_efekti_aktif or sprite is None or rect is None:
        return
    simdi = pygame.time.get_ticks()
    if simdi >= int(oyuncu_fire_burn_until):
        return
    renk, alfa = _fire_magic_flash_renk(simdi)
    sprite_maskeli_parlama_ciz(sprite, rect, renk, int(alfa * 0.46))
    _fire_magic_burn_flames_ciz(rect, 311, simdi)


def _fire_magic_hedef_kaydi():
    """
    Explosion resolver için immutable snapshot.

    Listeyi patlamanın başında almak, bir hedef 672 hasarla ölünce `common_enemies`
    üzerinde iterasyon yan etkisi oluşmasını engeller.
    """
    kayitlar = []
    if oyuncu_hp > 0:
        kayitlar.append(
            {
                "kind": "player",
                "obj": None,
                "pos": pygame.Vector2(float(oyuncu_x), float(oyuncu_y) - 8.0),
                "radius": 17.0,
            }
        )
    for dusman in _magic_hedefleri():
        kayitlar.append(
            {
                "kind": "enemy",
                "obj": dusman,
                "pos": pygame.Vector2(float(dusman.x), float(dusman.y) - 8.0),
                "radius": _magic_hedef_yaricapi(dusman),
            }
        )
    return kayitlar


def _stage1_fire_magic_patlama_hasari_uygula(x, y, simdi, direction=None):
    """V30 dört katmanlı kompakt blast resolver.

    0 / merkez   : 672-678, center dismemberment
    1. katman    : 422-428, birkaç kopma fakat gövde korunur
    2. katman    : 224-230, ölüm olursa burn/fire death
    3. katman    : 26-32, yalnız zayıf şok; ölüm olursa normal kanlı düşüş
    """
    global oyuncu_hp

    merkez = pygame.Vector2(float(x), float(y))
    momentum_dir = pygame.Vector2(direction or (0.0, 0.0))
    sonuc = []
    for kayit in _fire_magic_hedef_kaydi():
        hedef_pos = pygame.Vector2(kayit["pos"])
        geometrik = merkez.distance_to(hedef_pos)
        etkin = max(0.0, geometrik - float(kayit["radius"]) * 0.35)
        shell_id, band_radius = _fire_magic_band_sec(etkin)
        if shell_id <= 0:
            continue

        if geometrik > 12.0 and not _ince_dunya_los_acik_mi(merkez, hedef_pos, 4.5):
            continue

        radial = hedef_pos - merkez
        seed = int(simdi * 31 + hedef_pos.x * 17 + hedef_pos.y * 29 + shell_id * 101)
        hasar = _v30_fire_magic_hasar_roll(
            shell_id,
            etkin,
            band_radius,
            momentum_dir,
            radial,
            seed,
        )
        death_mode = FIRE_MAGIC_EXPLOSION_DEATH_MODES.get(int(shell_id), "blood")
        knock_speed = float(FIRE_MAGIC_KNOCKBACK_SPEEDS.get(int(shell_id), 180.0))
        burn_total = _fire_magic_burn_total(shell_id)

        if kayit["kind"] == "player":
            gercek_hasar = min(int(hasar), max(0, int(oyuncu_hp)))
            if gercek_hasar <= 0:
                continue
            oyuncu_hp = max(0, int(oyuncu_hp) - gercek_hasar)

            if death_mode == "blast_core":
                profile, source = (
                    "magic_heavy",
                    "fire_magic_explosion_core",
                )
            elif death_mode == "blast_inner":
                profile, source = (
                    "magic_heavy",
                    "fire_magic_explosion_inner",
                )
            elif death_mode == "fire":
                profile, source = (
                    "burn",
                    "fire_magic_explosion_burn",
                )
            elif death_mode == "blast_mid":




                profile, source = (
                    "medium_blunt",
                    "fire_magic_explosion_mid",
                )
            else:
                profile, source = (
                    "medium_blunt",
                    "fire_magic_explosion_shock",
                )

            oyuncu_kanli_hasar_kaydi(
                merkez.x,
                merkez.y,
                profile,
                gercek_hasar,
                source,
            )
            dunya_olayi_kaydet(
                "hit_taken",
                damage=gercek_hasar,
                count=1,
                enemy=source,
                self_hit=True,
                shell=int(shell_id),
            )
            _fire_magic_player_impulse_uygula(merkez, knock_speed, simdi)
            if oyuncu_hp > 0 and burn_total > 0:
                _fire_magic_burn_player_uygula(burn_total, simdi)
            sonuc.append(
                (
                    "player",
                    gercek_hasar,
                    geometrik,
                    int(shell_id),
                )
            )
        else:
            dusman = kayit["obj"]
            if death_mode in ("blast_core", "blast_inner"):
                profile = "magic_heavy"
            elif death_mode == "fire":
                profile = "burn"
            else:
                profile = "medium_blunt"
            kaynak = _V30FireDamageSource(merkez.x, merkez.y, profile)
            once_hp = int(getattr(dusman, "hp", 0))
            dusman.hasar_al(int(hasar), kaynak=kaynak)
            gercek_hasar = max(0, once_hp - int(getattr(dusman, "hp", 0)))
            _fire_magic_enemy_impulse_uygula(dusman, merkez, knock_speed, simdi)
            if (
                getattr(dusman, "active", False)
                and getattr(dusman, "hp", 0) > 0
                and burn_total > 0
            ):
                _fire_magic_burn_enemy_uygula(dusman, burn_total, simdi)
            dunya_olayi_kaydet(
                "fire_magic_hit",
                target=str(
                    getattr(
                        dusman,
                        "uid",
                        getattr(dusman, "tur", "enemy"),
                    )
                ),
                damage=gercek_hasar,
                shell=int(shell_id),
            )
            sonuc.append(
                (
                    str(getattr(dusman, "uid", "enemy")),
                    gercek_hasar,
                    geometrik,
                    int(shell_id),
                )
            )

    return sonuc


fire_magic_patlama_hasari_uygula = _stage1_fire_magic_patlama_hasari_uygula
# </POTBO_STAGE S0454>

# <POTBO_STAGE S0457>


def fire_magic_ground_fire_temasi_uygula(x, y, simdi):
    """Zemin alevine temas eden canlıyı yakar ve hafifçe geri iter.

    Cooldown hedef bazlıdır. Böylece 30 patch'in kesiştiği noktada tek karede ölüm
    oluşmaz; oyuncu alev alanında kalırsa periyodik olarak yeniden temas hasarı alır.
    """
    global oyuncu_hp
    merkez = pygame.Vector2(float(x), float(y))
    simdi = int(simdi)



    if oyuncu_hp > 0:
        p = pygame.Vector2(float(oyuncu_x), float(oyuncu_y) - 5.0)
        if merkez.distance_to(p) <= FIRE_MAGIC_GROUND_FIRE_TOUCH_RADIUS + 11.0:
            key = _fire_ground_target_cooldown_key(None)
            if simdi >= int(fire_ground_touch_cooldowns.get(key, 0)):
                fire_ground_touch_cooldowns[key] = (
                    simdi + FIRE_MAGIC_GROUND_FIRE_TOUCH_COOLDOWN_MS
                )
                hasar = min(
                    FIRE_MAGIC_GROUND_FIRE_TOUCH_DAMAGE,
                    max(0, int(oyuncu_hp)),
                )
                if hasar > 0:
                    oyuncu_hp = max(0, int(oyuncu_hp) - int(hasar))


                    oyuncu_kanli_hasar_kaydi(x, y, "burn", hasar, "ground_fire")
                    dunya_olayi_kaydet(
                        "hit_taken",
                        damage=hasar,
                        count=1,
                        enemy="ground_fire",
                        self_hit=True,
                    )
                    _fire_magic_player_impulse_uygula(
                        merkez,
                        FIRE_MAGIC_GROUND_FIRE_KNOCKBACK,
                        simdi,
                    )
                    if oyuncu_hp > 0:
                        _fire_magic_burn_player_uygula(
                            FIRE_MAGIC_GROUND_FIRE_BURN_TOTAL,
                            simdi,
                        )


    for dusman in list(_magic_hedefleri()):
        if (
            dusman is None
            or not getattr(dusman, "active", False)
            or getattr(dusman, "hp", 0) <= 0
        ):
            continue
        pos = pygame.Vector2(float(dusman.x), float(dusman.y) - 5.0)
        temas_r = (
            FIRE_MAGIC_GROUND_FIRE_TOUCH_RADIUS + _magic_hedef_yaricapi(dusman) * 0.32
        )
        if merkez.distance_to(pos) > temas_r:
            continue
        key = _fire_ground_target_cooldown_key(dusman)
        if simdi < int(fire_ground_touch_cooldowns.get(key, 0)):
            continue
        fire_ground_touch_cooldowns[key] = (
            simdi + FIRE_MAGIC_GROUND_FIRE_TOUCH_COOLDOWN_MS
        )
        once_hp = int(getattr(dusman, "hp", 0))
        dusman.hasar_al(int(FIRE_MAGIC_GROUND_FIRE_TOUCH_DAMAGE))
        gercek = max(0, once_hp - int(getattr(dusman, "hp", 0)))
        _fire_magic_enemy_impulse_uygula(
            dusman,
            merkez,
            FIRE_MAGIC_GROUND_FIRE_KNOCKBACK,
            simdi,
        )
        if getattr(dusman, "active", False) and getattr(dusman, "hp", 0) > 0:
            _fire_magic_burn_enemy_uygula(
                dusman, FIRE_MAGIC_GROUND_FIRE_BURN_TOTAL, simdi
            )
        if gercek > 0:
            dunya_olayi_kaydet(
                "ground_fire_hit",
                target=str(
                    getattr(
                        dusman,
                        "uid",
                        getattr(dusman, "tur", "enemy"),
                    )
                ),
                damage=gercek,
            )


class GroundFirePatch:
    """
    Patlama sonrası kısa ömürlü zemin ateşi.

    V29'da yalnız dekor değildir. Temas eden oyuncu veya düşmana küçük doğrudan hasar,
    gerçek burn durumu ve hafif blast-yönlü geri itme uygular. Hedef bazlı cooldown
    üst üste duran alevlerin aynı karede hasarı katlamasını engeller.
    """

    def __init__(self, x, y, simdi, index=0):
        self.x = float(x)
        self.y = float(y)
        self.start_ms = int(simdi)
        rng = random.Random(int(x * 19 + y * 31 + simdi * 0.17 + index * 997))
        self.duration_ms = rng.randint(
            FIRE_MAGIC_GROUND_FIRE_MIN_MS,
            FIRE_MAGIC_GROUND_FIRE_MAX_MS,
        )
        self.seed = rng.randint(0, 100000)
        self.scale = rng.uniform(0.72, 1.18)
        _family_names = tuple(FIRE_MAGIC_GROUND_AILELERI.keys())
        self.family_name = rng.choice(_family_names) if _family_names else None
        self.frame_offset = rng.randint(
            0,
            max(
                0,
                len(
                    FIRE_MAGIC_GROUND_AILELERI.get(
                        self.family_name,
                        FIRE_MAGIC_GROUND_SPRITELERI,
                    )
                )
                - 1,
            ),
        )
        self.active = True

    def guncelle(self, simdi):
        if int(simdi) - self.start_ms >= self.duration_ms:
            self.active = False
            return
        fire_magic_ground_fire_temasi_uygula(self.x, self.y, simdi)

    def ciz(self):
        if not self.active or not FIRE_MAGIC_GROUND_SPRITELERI:
            return
        simdi = pygame.time.get_ticks()
        age = max(
            0.0,
            min(
                1.0,
                (simdi - self.start_ms) / max(1.0, float(self.duration_ms)),
            ),
        )

        fade_in = min(1.0, age / 0.12)
        fade_out = 1.0 if age < 0.72 else max(0.0, (1.0 - age) / 0.28)
        alpha = int(255 * fade_in * fade_out)
        if alpha <= 0:
            return

        family = FIRE_MAGIC_GROUND_AILELERI.get(
            self.family_name, FIRE_MAGIC_GROUND_SPRITELERI
        )
        if not family:
            return
        idx = (self.frame_offset + (simdi - self.start_ms) // 130) % len(family)
        frame = family[idx]
        pulse = 1.0 + 0.045 * math.sin(simdi * 0.021 + self.seed)
        h = max(
            10,
            int(round(frame.get_height() * self.scale * pulse * KAMERA_YAKINLASTIRMA)),
        )
        key = ("ground_fire_v12", id(frame), h)
        img = sprite_olcek_onbellegi.get(key)
        if img is None:
            sc = h / max(1.0, float(frame.get_height()))
            img = pygame.transform.scale(
                frame,
                (max(1, int(round(frame.get_width() * sc))), h),
            )
            sprite_olcek_onbellegi[key] = img

        draw = img
        if alpha < 250:
            draw = img.copy()
            draw.set_alpha(alpha)

        sx = dunya_ekran_x(self.x)
        sy = dunya_ekran_y(self.y)
        ekran.blit(draw, draw.get_rect(midbottom=(sx, sy + 3)))


class FireMagicExplosion:
    """Projectile temas ettiği karede patlayan blast nesnesi.

    V26'da fuse kaldırıldı: hasar, knockback, flash ve ses aynı detonation anında doğar.
    """

    def __init__(self, x, y, simdi, direction=None):
        self.x = float(x)
        self.y = float(y)
        self.impact_ms = int(simdi)
        self.detonate_ms = int(simdi) + FIRE_MAGIC_EXPLOSION_DELAY_MS
        self.explosion_start_ms = 0
        self.active = True
        self.detonated = False
        self.sound_played = False
        self.duration_ms = 880
        self.direction = pygame.Vector2(direction or (0.0, 0.0))
        self.hits = []

    def _detonate(self, simdi):
        if self.detonated:
            return
        self.detonated = True
        self.explosion_start_ms = int(simdi)
        self.hits = fire_magic_patlama_hasari_uygula(
            self.x, self.y, simdi, self.direction
        )

        patch_count = random.Random(int(self.x * 13 + self.y * 29 + simdi)).randint(
            FIRE_MAGIC_GROUND_FIRE_MIN,
            FIRE_MAGIC_GROUND_FIRE_MAX,
        )
        for i, p in enumerate(
            _fire_ground_spawn_noktalari(
                self.x,
                self.y,
                patch_count,
                FIRE_MAGIC_GROUND_FIRE_RADIUS,
            )
        ):
            player_magic_ground_fires.append(GroundFirePatch(p.x, p.y, simdi, i))

        fire_magic_screen_flash_baslat(simdi)
        kamera_hit_sarsintisi_baslat(19.5, 520)


        if FIRE_MAGIC_EXPLOSION_SOUND_OFFSET_MS <= 0:
            fire_magic_sesi_cal("explosion")
            self.sound_played = True

    def guncelle(self, simdi):
        simdi = int(simdi)
        if not self.detonated and simdi >= self.detonate_ms:
            self._detonate(simdi)

        if self.detonated and not self.sound_played:
            ses_an = self.explosion_start_ms + FIRE_MAGIC_EXPLOSION_SOUND_OFFSET_MS
            if simdi >= ses_an:
                fire_magic_sesi_cal("explosion")
                self.sound_played = True

        if self.detonated and simdi - self.explosion_start_ms >= self.duration_ms:
            self.active = False

    def _impact_core_ciz(self, ex, ey, simdi):


        if not FIRE_MAGIC_STRETCH_SPRITELERI:
            return
        frame = FIRE_MAGIC_STRETCH_SPRITELERI[-1]
        kalan = max(0, self.detonate_ms - int(simdi))
        p = 1.0 - min(
            1.0,
            kalan / max(1.0, float(FIRE_MAGIC_EXPLOSION_DELAY_MS)),
        )
        pulse = 0.94 + 0.09 * math.sin(p * math.pi * 5.0) + 0.08 * p
        h = int(
            round(
                64 * FIRE_MAGIC_PROJECTILE_VISUAL_SCALE * pulse * KAMERA_YAKINLASTIRMA
            )
        )
        d = self.direction
        yon = (
            "left"
            if d.x < -0.5
            else "right"
            if d.x > 0.5
            else "up"
            if d.y < 0
            else "down"
        )
        key = ("fire_impact_fuse_v25", id(frame), h, yon)
        img = sprite_olcek_onbellegi.get(key)
        if img is None:
            sc = h / max(1.0, float(frame.get_height()))
            base = pygame.transform.scale(
                frame,
                (max(1, int(round(frame.get_width() * sc))), h),
            )
            img = _fire_cast_sprite_yone_cevir(base, yon)
            sprite_olcek_onbellegi[key] = img
        ekran.blit(img, img.get_rect(center=(ex, ey - 12)))

    def ciz(self):
        if not self.active:
            return
        simdi = pygame.time.get_ticks()
        ex = dunya_ekran_x(self.x)
        ey = dunya_ekran_y(self.y)

        if not self.detonated:
            self._impact_core_ciz(ex, ey, simdi)
            return

        gecen = max(0, int(simdi) - int(self.explosion_start_ms))
        oran = min(0.999, gecen / max(1.0, float(self.duration_ms)))
        if FIRE_MAGIC_EXPLOSION_SPRITELERI:
            idx = min(
                len(FIRE_MAGIC_EXPLOSION_SPRITELERI) - 1,
                int(oran * len(FIRE_MAGIC_EXPLOSION_SPRITELERI)),
            )
            frame = FIRE_MAGIC_EXPLOSION_SPRITELERI[idx]
            h = int(
                round(122 * FIRE_MAGIC_EXPLOSION_VISUAL_SCALE * KAMERA_YAKINLASTIRMA)
            )
            key = ("fire_explosion_v25", id(frame), h)
            img = sprite_olcek_onbellegi.get(key)
            if img is None:
                sc = h / max(1.0, float(frame.get_height()))
                img = pygame.transform.scale(
                    frame,
                    (
                        max(
                            1,
                            int(round(frame.get_width() * sc)),
                        ),
                        h,
                    ),
                )
                sprite_olcek_onbellegi[key] = img
            ekran.blit(img, img.get_rect(midbottom=(ex, ey + 12)))


class FireMagicProjectile:
    """
    Homing olmayan gerçek projectile.

    Continuous collision substeps = yüksek hızda ince engelleri atlamaz.
    Hedefe/duvara değmezse kendi başına "uzakta patlamaz"; dünya sınırından veya
    safety TTL'den sonra sessizce söner.
    """

    def __init__(self, x, y, direction, simdi):
        self.x = float(x)
        self.y = float(y)
        self.start = pygame.Vector2(x, y)
        self.direction = pygame.Vector2(direction)
        if self.direction.length_squared() <= 1e-6:
            self.direction = pygame.Vector2(1.0, 0.0)
        self.direction = self.direction.normalize()
        self.v = self.direction * FIRE_MAGIC_PROJECTILE_SPEED
        self.start_ms = int(simdi)
        self.active = True
        self.anim_epoch = int(simdi)
        self.travelled = 0.0

    def _patlat(self, simdi):
        if not self.active:
            return
        self.active = False
        player_magic_explosions.append(
            FireMagicExplosion(self.x, self.y, simdi, self.direction)
        )

    def _dunya_disinda_mi(self):
        margin = 70.0
        return (
            self.x < -margin
            or self.y < -margin
            or self.x > HARITA_GENISLIK + margin
            or self.y > HARITA_YUKSEKLIK + margin
        )

    def guncelle(self, dt, simdi):
        if not self.active:
            return

        if (
            int(simdi) - self.start_ms >= FIRE_MAGIC_PROJECTILE_TTL_MS
            or self.travelled >= FIRE_MAGIC_PROJECTILE_MAX_TRAVEL
            or self._dunya_disinda_mi()
        ):

            self.active = False
            return

        toplam = max(0.0, self.v.length() * max(0.0, float(dt)))
        kalan = toplam
        while kalan > 0.0 and self.active:
            adim = min(4.0, kalan)
            eski = pygame.Vector2(self.x, self.y)
            yeni = eski + self.direction * adim



            if harita_pikseli_engel_mi(yeni.x, yeni.y):
                self.x, self.y = eski.x, eski.y
                self._patlat(simdi)
                break


            hit = None
            for dusman in _magic_hedefleri():
                radius = _magic_hedef_yaricapi(dusman) + FIRE_MAGIC_PROJECTILE_RADIUS
                if yeni.distance_to((float(dusman.x), float(dusman.y) - 7.0)) <= radius:
                    hit = dusman
                    break

            self.x, self.y = yeni.x, yeni.y
            self.travelled += adim
            kalan -= adim

            if hit is not None:
                self._patlat(simdi)
                break

    def ciz(self):
        if not self.active or not FIRE_MAGIC_PROJECTILE_SPRITELERI:
            return

        ex = dunya_ekran_x(self.x)
        ey = dunya_ekran_y(self.y)
        simdi = pygame.time.get_ticks()
        yas = max(0, simdi - self.anim_epoch)
        if len(FIRE_MAGIC_PROJECTILE_SPRITELERI) >= 3:



            idx = 0 if yas < 60 else 1 if yas < 120 else 2
        else:
            idx = min(
                len(FIRE_MAGIC_PROJECTILE_SPRITELERI) - 1,
                yas // 70,
            )
        frame = FIRE_MAGIC_PROJECTILE_SPRITELERI[idx]
        h = int(round(60 * FIRE_MAGIC_PROJECTILE_VISUAL_SCALE * KAMERA_YAKINLASTIRMA))
        direction_name = (
            "left"
            if self.direction.x < -0.5
            else "right"
            if self.direction.x > 0.5
            else "up"
            if self.direction.y < 0
            else "down"
        )
        key = (
            "fire_projectile_v15",
            id(frame),
            h,
            direction_name,
        )
        img = sprite_olcek_onbellegi.get(key)
        if img is None:
            sc = h / max(1.0, float(frame.get_height()))
            img = pygame.transform.scale(
                frame,
                (max(1, int(round(frame.get_width() * sc))), h),
            )

            if direction_name == "up":
                img = pygame.transform.rotate(img, 180)
            elif direction_name == "right":
                img = pygame.transform.rotate(img, 90)
            elif direction_name == "left":
                img = pygame.transform.rotate(img, -90)
            sprite_olcek_onbellegi[key] = img



        _v27_ates_pariltisi_ciz(img, ex, ey - 13, simdi, guc=1.38)
        for i, (offset, alpha) in enumerate(((20.0, 118), (38.0, 70), (58.0, 34))):
            px = ex - self.direction.x * offset * KAMERA_YAKINLASTIRMA
            py = ey - 13 - self.direction.y * offset * KAMERA_YAKINLASTIRMA
            ghost = img.copy()
            ghost.set_alpha(alpha)
            ekran.blit(ghost, ghost.get_rect(center=(int(px), int(py))))
        ekran.blit(img, img.get_rect(center=(ex, ey - 13)))


def fire_magic_kullan():
    global oyuncu_mana, oyuncu_stamina, stamina_son_harcama
    global fire_magic_son_kullanim, fire_magic_cast_lock_until, fire_magic_cast_fx

    if oyun_durumu != OYUN or oyun_alt_durumu != HARITA or oyuncu_hp <= 0:
        return False

    simdi = pygame.time.get_ticks()
    if (
        oyuncu_saldiriyor
        or simdi < oyuncu_baygin_bitis
        or simdi < fire_magic_cast_lock_until
    ):
        return False

    debug_bedelsiz = bool(gelistirici_sonsuz_ates)
    kalan = FIRE_MAGIC_COOLDOWN_MS - (simdi - fire_magic_son_kullanim)
    if kalan > 0 and not debug_bedelsiz:
        bildirim_goster(
            bt(
                "Ateş henüz yeniden toplanmadı.",
                "The fire has not gathered again yet.",
            )
        )
        return False

    if oyuncu_mana < FIRE_MAGIC_MANA_MALIYETI and not debug_bedelsiz:
        hud_uyari_baslat("mana")
        bildirim_goster(bt("50 mana gerekiyor.", "50 mana required."))
        return False

    if not debug_bedelsiz:
        oyuncu_mana = max(0, oyuncu_mana - FIRE_MAGIC_MANA_MALIYETI)
        oyuncu_stamina = 0.0
        stamina_son_harcama = simdi
        fire_magic_son_kullanim = simdi
    else:


        fire_magic_son_kullanim = simdi - FIRE_MAGIC_COOLDOWN_MS
    fire_magic_cast_lock_until = simdi + FIRE_MAGIC_CAST_LOCK_MS

    yon = _yon_vektoru(oyuncu_yonu)
    origin = pygame.Vector2(float(oyuncu_x), float(oyuncu_y))
    focus = origin + yon * FIRE_MAGIC_CAST_FORWARD_OFFSET



    if harita_pikseli_engel_mi(focus.x, focus.y):
        found = None
        for back in (8.0, 14.0, 20.0, 26.0, 32.0):
            p = focus - yon * back
            if not harita_pikseli_engel_mi(p.x, p.y):
                found = p
                break
        if found is not None:
            focus = found
        else:
            focus = origin + yon * 12.0


    fire_magic_sesi_cal("charge")
    fire_magic_cast_fx = {
        "start_ms": simdi,
        "origin_x": origin.x,
        "origin_y": origin.y,
        "x": float(focus.x),
        "y": float(focus.y),
        "direction": (yon.x, yon.y),
        "ready_sound_played": True,
        "launched": False,
    }
    dunya_olayi_kaydet(
        "fire_magic_cast",
        direction=str(oyuncu_yonu),
        mana=0 if debug_bedelsiz else FIRE_MAGIC_MANA_MALIYETI,
        developer_free=debug_bedelsiz,
    )
    return True


def fire_magic_guncelle(dt, simdi):
    global fire_magic_cast_fx

    fire_magic_player_status_guncelle(simdi)

    if fire_magic_cast_fx is not None:
        fx = fire_magic_cast_fx
        gecen = simdi - int(fx["start_ms"])




        if (
            not fx.get("ready_sound_played", False)
            and gecen >= FIRE_MAGIC_CHARGE_READY_SOUND_MS
        ):
            fire_magic_sesi_cal("charge")
            fx["ready_sound_played"] = True

        if not fx.get("launched", False) and gecen >= FIRE_MAGIC_CAST_RELEASE_MS:
            d = pygame.Vector2(fx["direction"])
            bas = pygame.Vector2(float(fx["x"]), float(fx["y"]))

            fire_magic_sesi_cal("whoosh")
            player_magic_projectiles.append(FireMagicProjectile(bas.x, bas.y, d, simdi))
            fx["launched"] = True

        if gecen >= FIRE_MAGIC_CAST_TOTAL_MS:
            fire_magic_cast_fx = None

    for projectile in list(player_magic_projectiles):
        projectile.guncelle(dt, simdi)
    player_magic_projectiles[:] = [p for p in player_magic_projectiles if p.active]

    for explosion in list(player_magic_explosions):
        explosion.guncelle(simdi)
    player_magic_explosions[:] = [e for e in player_magic_explosions if e.active]

    for patch in list(player_magic_ground_fires):
        patch.guncelle(simdi)
    player_magic_ground_fires[:] = [f for f in player_magic_ground_fires if f.active]
