def fire_magic_alt_katman_ciz():
    """Hızlı ve akıcı halka -> küre -> uzayan alev dönüşümü."""
    if fire_magic_cast_fx is None:
        return
    simdi = pygame.time.get_ticks()
    gecen = max(0, simdi - int(fire_magic_cast_fx["start_ms"]))
    release_p = max(
        0.0,
        min(
            1.0,
            gecen / max(1.0, float(FIRE_MAGIC_CAST_RELEASE_MS)),
        ),
    )
    x = dunya_ekran_x(fire_magic_cast_fx["x"])
    y = dunya_ekran_y(fire_magic_cast_fx["y"])
    dx, dy = fire_magic_cast_fx.get("direction", (1.0, 0.0))
    yon = "left" if dx < -0.5 else "right" if dx > 0.5 else "up" if dy < 0 else "down"



    cekirdek_x = x
    cekirdek_y = y - 11


    ring_end = 0.50
    if release_p < ring_end and FIRE_MAGIC_CAST_SPRITELERI:
        ring_p = min(1.0, release_p / ring_end)
        frame_pos = ring_p * max(0, len(FIRE_MAGIC_CAST_SPRITELERI) - 1)
        idx = min(len(FIRE_MAGIC_CAST_SPRITELERI) - 1, int(frame_pos))
        frame = FIRE_MAGIC_CAST_SPRITELERI[idx]
        collapse = max(
            0.0,
            (release_p - FIRE_MAGIC_ORB_START_RATIO)
            / max(0.01, ring_end - FIRE_MAGIC_ORB_START_RATIO),
        )
        h = max(
            20,
            int(
                round(
                    (72 - 30 * collapse)
                    * FIRE_MAGIC_CAST_VISUAL_SCALE
                    * KAMERA_YAKINLASTIRMA
                )
            ),
        )
        key = ("fire_cast_ring_v17", id(frame), h)
        img = sprite_olcek_onbellegi.get(key)
        if img is None:
            sc = h / max(1.0, float(frame.get_height()))
            img = pygame.transform.scale(
                frame,
                (max(1, int(round(frame.get_width() * sc))), h),
            )
            sprite_olcek_onbellegi[key] = img
        draw = img
        if release_p > 0.38:
            draw = img.copy()
            draw.set_alpha(
                int(
                    255
                    * max(
                        0.0,
                        (ring_end - release_p) / (ring_end - 0.38),
                    )
                )
            )
        _alpha_bounds_merkez_bastir(draw, cekirdek_x, cekirdek_y)





    if release_p >= FIRE_MAGIC_ORB_START_RATIO and FIRE_MAGIC_ORB_SPRITELERI:
        orb_end = FIRE_MAGIC_STRETCH_START_RATIO
        orb_p = min(
            1.0,
            (release_p - FIRE_MAGIC_ORB_START_RATIO)
            / max(0.01, orb_end - FIRE_MAGIC_ORB_START_RATIO),
        )
        frame_pos = orb_p * max(0, len(FIRE_MAGIC_ORB_SPRITELERI) - 1)
        idx = min(
            len(FIRE_MAGIC_ORB_SPRITELERI) - 1,
            int(frame_pos + 0.12),
        )
        frame = FIRE_MAGIC_ORB_SPRITELERI[idx]

        ease = 1.0 - (1.0 - orb_p) ** 2.2
        h = int(round((24 + 40 * ease) * KAMERA_YAKINLASTIRMA))
        key = ("fire_cast_orb_v17", id(frame), h)
        img = sprite_olcek_onbellegi.get(key)
        if img is None:
            sc = h / max(1.0, float(frame.get_height()))
            img = pygame.transform.scale(
                frame,
                (max(1, int(round(frame.get_width() * sc))), h),
            )
            sprite_olcek_onbellegi[key] = img

        alpha = 255
        if release_p >= FIRE_MAGIC_STRETCH_START_RATIO:
            alpha = int(
                255
                * max(
                    0.0,
                    1.0 - (release_p - FIRE_MAGIC_STRETCH_START_RATIO) / 0.16,
                )
            )
        draw = img if alpha >= 250 else img.copy()
        if draw is not img:
            draw.set_alpha(alpha)
        _v27_ates_pariltisi_ciz(
            draw,
            cekirdek_x,
            cekirdek_y,
            simdi,
            guc=1.05 + 0.22 * orb_p,
        )
        _alpha_bounds_merkez_bastir(draw, cekirdek_x, cekirdek_y)



    if release_p >= FIRE_MAGIC_STRETCH_START_RATIO and FIRE_MAGIC_STRETCH_SPRITELERI:
        stretch_p = min(
            1.0,
            (release_p - FIRE_MAGIC_STRETCH_START_RATIO)
            / max(0.01, 1.0 - FIRE_MAGIC_STRETCH_START_RATIO),
        )
        frame_pos = stretch_p * max(0, len(FIRE_MAGIC_STRETCH_SPRITELERI) - 1)
        idx = min(
            len(FIRE_MAGIC_STRETCH_SPRITELERI) - 1,
            int(frame_pos + 0.18),
        )
        frame = FIRE_MAGIC_STRETCH_SPRITELERI[idx]
        h = int(
            round(
                (42 + 24 * stretch_p)
                * FIRE_MAGIC_PROJECTILE_VISUAL_SCALE
                * KAMERA_YAKINLASTIRMA
            )
        )
        key = ("fire_cast_stretch_v17", id(frame), h, yon)
        img = sprite_olcek_onbellegi.get(key)
        if img is None:
            sc = h / max(1.0, float(frame.get_height()))
            base = pygame.transform.scale(
                frame,
                (max(1, int(round(frame.get_width() * sc))), h),
            )
            img = _fire_cast_sprite_yone_cevir(base, yon)
            sprite_olcek_onbellegi[key] = img
        _v27_ates_pariltisi_ciz(
            img,
            cekirdek_x,
            cekirdek_y,
            simdi,
            guc=1.22 + 0.18 * stretch_p,
        )
        _alpha_bounds_merkez_bastir(img, cekirdek_x, cekirdek_y)


