def oyuncu_savunma_guncelle():
    global oyuncu_savunuyor, savunma_zincir_vurus, savunma_son_guncelleme
    global oyuncu_stamina, stamina_son_harcama
    simdi = pygame.time.get_ticks()
    dt = max(
        0.0,
        min(0.05, (simdi - savunma_son_guncelleme) / 1000.0),
    )
    savunma_son_guncelleme = simdi
    try:
        basili = bool(potbo_pressed_state()[tus_atamasi("block")])
    except (pygame.error, IndexError, TypeError):
        basili = False

    uygun = (
        oyun_durumu == OYUN
        and oyun_alt_durumu == HARITA
        and oyuncu_hp > 0
        and not oyun_sinematik_kilitli_mi()
        and simdi >= oyuncu_baygin_bitis
        and simdi >= fire_magic_cast_lock_until
        and not gelistirici_x_skill_aktif_mi(simdi)
        and not oyuncu_saldiriyor
        and not oyuncu_dash_aktif_mi(simdi)
    )
    oyuncu_savunuyor = bool(basili and uygun and oyuncu_stamina > 0.0)
    if oyuncu_savunuyor and dt > 0.0:
        oyuncu_stamina = max(
            0.0,
            oyuncu_stamina - SAVUNMA_TUTMA_STAMINA_SANIYE * dt,
        )
        stamina_son_harcama = simdi
        if oyuncu_stamina <= 0.0:
            oyuncu_savunuyor = False
            hud_uyari_baslat("stamina")
    elif simdi - savunma_son_temasi >= SAVUNMA_ZINCIR_SIFIRLAMA_MS:
        savunma_zincir_vurus = 0
