def _v25_oyuncu_olum_ates_ciz():
    """Yanarak ölümde çok sayıda, yalnız kırmızı silhouette alev kullanır.

    Kaynak atlasın sarı/turuncu renkleri ölüm tablosuna taşınmaz; her flame frame'i
    maskeye çevrilip kırmızıya tint edilir. Böylece siyah-kırmızı ölüm dili korunur.
    """
    if oyuncu_olum_turu != "fire" or not FIRE_MAGIC_GROUND_SPRITELERI:
        return
    simdi = pygame.time.get_ticks()
    sx = float(dunya_ekran_x(oyuncu_x))
    sy = float(dunya_ekran_y(oyuncu_y))
    seed = int(oyuncu_olum_ates_seed or 911)
    rng = random.Random(seed)



    noktalar = []
    adet = 36
    for i in range(adet):
        t = -1.0 + (2.0 * i / max(1.0, adet - 1.0))
        yay = math.sin((t + 1.0) * math.pi) * 6.0
        noktalar.append(
            (
                sx + t * 39.0 + rng.uniform(-6.0, 6.0),
                sy - yay + rng.uniform(-9.0, 7.0),
                rng.uniform(0.30, 0.60),
                rng.randint(0, 999),
            )
        )

    for i, (px, py, scale_mul, phase) in enumerate(noktalar):
        idx = (int(simdi // 78) + phase + i * 3) % len(FIRE_MAGIC_GROUND_SPRITELERI)
        frame = FIRE_MAGIC_GROUND_SPRITELERI[idx]
        pulse = 1.0 + 0.10 * math.sin(simdi * 0.030 + phase * 0.017)
        h = max(
            8,
            int(round(42.0 * scale_mul * pulse * KAMERA_YAKINLASTIRMA)),
        )
        key = ("death_fire_red_v27", id(frame), h)
        img = sprite_olcek_onbellegi.get(key)
        if img is None:
            sc = h / max(1.0, float(frame.get_height()))
            scaled = pygame.transform.scale(
                frame,
                (max(1, int(round(frame.get_width() * sc))), h),
            )
            mask = pygame.mask.from_surface(scaled)
            img = mask.to_surface(
                setcolor=(230, 8, 28, 235),
                unsetcolor=(0, 0, 0, 0),
            ).convert_alpha()
            sprite_olcek_onbellegi[key] = img
        ekran.blit(
            img,
            img.get_rect(midbottom=(int(round(px)), int(round(py + 8)))),
        )
