def gelistirici_test_girdisi_uygula(olay):
    """Yalnız istenen dört CTRL test kısayolunu uygular; U yalnız prototip kilididir."""
    if not GELISTIRICI_MODU:
        return False

    global oyuncu_altin, gelistirici_sonsuz_ates, gelistirici_x_skill_aktif
    if olay.type != pygame.KEYDOWN or not (olay.mod & pygame.KMOD_CTRL):
        return False

    if olay.key == pygame.K_i:
        oyuncu_altin += 100
        bildirim_goster(bt("+100 coin", "+100 coins"))

    elif olay.key == pygame.K_l:
        level_test_arttir()

    elif olay.key == pygame.K_o:
        gelistirici_sonsuz_ates = not gelistirici_sonsuz_ates
        bildirim_goster(
            bt(
                "Sonsuz Sphaera AÇIK: Q beklemesiz, mana ve stamina harcamaz."
                if gelistirici_sonsuz_ates
                else "Sonsuz Sphaera KAPALI.",
                "Infinite Sphaera ON: Q has no cooldown and spends no mana or stamina."
                if gelistirici_sonsuz_ates
                else "Infinite Sphaera OFF.",
            ),
            (255, 132, 38) if gelistirici_sonsuz_ates else GRI,
        )

    elif olay.key == pygame.K_u:
        gelistirici_x_skill_aktif = not gelistirici_x_skill_aktif
        gelistirici_x_skill_sifirla(True)
        bildirim_goster(
            bt(
                "Özel hareket testi AÇIK: hold-to-attack sırasında R'ye bas ve R'yi bırak."
                if gelistirici_x_skill_aktif
                else "Özel hareket testi KAPALI.",
                "Special move test ON: while charging hold-to-attack, press and release R."
                if gelistirici_x_skill_aktif
                else "Special move test OFF.",
            ),
            (230, 42, 68) if gelistirici_x_skill_aktif else GRI,
        )

    else:
        return False
    return True
