def _stage2_oyuncu_kanli_hasar_kaydi(kaynak_x, kaynak_y, profil, hasar, kaynak_adi=""):
    """V31 hasar kontratını korur; yalnız ölüm sunumunun türünü düzeltir.

    * Torrmund dışındaki heavy-slash ölümleri artık temiz iki yarıya bölünmez.
    * Patlamanın 224-230 halkası doğrudan fire-death değildir. Patlama o anda
      öldürürse orta blast parçalanması görülür. Yanarak ölüm ancak aktif burn DoT
      tick'inin lethal olmasıyla oluşur.
    """
    global oyuncu_olum_ikiye_bolundu, oyuncu_olum_turu, oyuncu_olum_alt_turu
    global oyuncu_olum_patlama_seed, oyuncu_olum_patlama_yonu
    global \
        oyuncu_olum_katil_uid, \
        oyuncu_olum_katil_tur, \
        oyuncu_olum_katil_kan_sonraki_ms

    _v31_kanli_hasar_kaydi(kaynak_x, kaynak_y, profil, hasar, kaynak_adi)

    lethal = oyuncu_hp <= 0
    if not lethal:
        return

    kaynak = str(kaynak_adi or "")



    if str(oyuncu_olum_katil_tur or "") != "torrmund":
        oyuncu_olum_ikiye_bolundu = False

    if kaynak == "fire_magic_explosion_mid":
        oyuncu_olum_turu = "blast_mid"
        oyuncu_olum_alt_turu = "blast_mid"
        oyuncu_olum_patlama_seed = random.randint(1, 2_000_000)
        blast_yon = pygame.Vector2(
            oyuncu_x - float(kaynak_x),
            oyuncu_y - float(kaynak_y),
        )
        if blast_yon.length_squared() <= 1e-6:
            blast_yon = pygame.Vector2(1.0, 0.0).rotate(random.uniform(0.0, 360.0))
        oyuncu_olum_patlama_yonu = blast_yon.normalize()
        oyuncu_olum_katil_uid = ""
        oyuncu_olum_katil_tur = ""
