def _kan_profil_degerleri(profil, lethal=False):
    tablo = {
        "burn": (4, 1, 0.62),
        "light_slash": (11, 2, 0.84),
        "slash": (17, 3, 1.03),
        "medium_blunt": (21, 3, 1.14),
        "medium_slash": (27, 4, 1.28),
        "magic_heavy": (34, 6, 1.48),
        "heavy_blunt": (43, 7, 1.66),
        "heavy_slash": (54, 9, 1.90),
    }
    parcacik, leke, guc = tablo.get(str(profil), tablo["slash"])
    if lethal:
        parcacik = int(parcacik * 2.28) + 14
        leke += 6
    return parcacik, leke, guc


def gore_olum_patlamasi(x, y, profil="slash", yon=None):
    heavy = profil in (
        "heavy_blunt",
        "heavy_slash",
        "magic_heavy",
    )
    medium = profil in ("medium_blunt", "medium_slash")
    if heavy:
        adet = random.randint(24, 32)
        guc = 1.62 if profil == "heavy_slash" else 1.42
    elif medium:
        adet = random.randint(13, 18)
        guc = 1.12
    else:
        adet = random.randint(8, 11)
        guc = 0.86

    kinds = list(GORE_SPRITELERI.keys()) or [
        "liver",
        "intestine",
    ]
    havuz = [
        "flesh_shard_a",
        "flesh_shard_b",
        "intestine",
        "liver",
        "organ_round_a",
        "organ_round_b",
        "organ_mass_a",
        "organ_mass_b",
        "bone_cluster_a",
        "bone_cluster_b",
        "bone_long_a",
        "bone_long_b",
        "ribcage",
        "spinal_cord",
        "skull",
        "leg",
        "foot",
        "intestine",
        "liver",
        "flesh_shard_a",
        "bone_cluster_a",
    ]
    havuz = [k for k in havuz if k in kinds] or kinds
    ana = pygame.Vector2(yon) if yon is not None else pygame.Vector2(0.0, 0.0)
    if ana.length_squared() > 1e-6:
        ana = ana.normalize()

    for i in range(adet):
        kind = random.choice(havuz)
        small = random.random() < (0.68 if heavy else 0.58)
        parca = GoreChunk(kind, x, y, guc=guc, small=small)
        if profil == "heavy_slash" and ana.length_squared() > 0.0:
            d = ana.rotate(random.uniform(-55.0, 55.0))
            if random.random() < 0.15:
                d *= -1.0
            d = d.normalize() if d.length_squared() > 1e-6 else ana
            parca.v = d * random.uniform(195.0, 370.0) * (0.78 if small else 1.0)
            parca.vz = random.uniform(170.0, 330.0)
            parca.angular = random.uniform(-590.0, 590.0)
        elif profil in ("heavy_blunt", "magic_heavy"):
            parca.v *= random.uniform(1.22, 1.62)
            parca.vz *= random.uniform(1.08, 1.36)
            parca.angular *= 1.25
        gore_chunks.append(parca)
