def v34_fx_budget_guncelle():
    """Uzun oturumda yalnız transient efekt havuzlarını sınırlar.

    Kalıcı blood_decals/gore tasarım kararı olarak korunur; burada yalnız zaten kısa
    ömürlü listelerin bir bug/hitch yüzünden birikmesi engellenir.
    """
    global v34_fx_budget_last_check
    simdi = pygame.time.get_ticks()
    if simdi - v34_fx_budget_last_check < V34_FX_BUDGET_CHECK_MS:
        return
    v34_fx_budget_last_check = simdi

    trimmed = 0
    trimmed += _v34_trim_oldest_in_place(blood_particles, V34_MAX_BLOOD_PARTICLES)
    trimmed += _v34_trim_oldest_in_place(combat_impact_fx, V34_MAX_COMBAT_IMPACTS)
    trimmed += _v34_trim_oldest_in_place(enemy_rock_impacts, V34_MAX_ROCK_IMPACTS)
    trimmed += _v34_trim_oldest_in_place(
        player_magic_projectiles, V34_MAX_PLAYER_PROJECTILES
    )
    trimmed += _v34_trim_oldest_in_place(
        player_magic_explosions, V34_MAX_PLAYER_EXPLOSIONS
    )
    trimmed += _v34_trim_oldest_in_place(
        player_magic_ground_fires, V34_MAX_GROUND_FIRES
    )
    if trimmed and DEBUG_LOGS:
        debug_log(
            "V34 transient FX budget trimmed",
            trimmed,
            "objects",
        )
