def _v38_settings_bootstrap():
    global v38_magic_fx_quality, v38_combat_precision
    global v38_fire_self_damage, v38_impact_pause
    try:
        if not os.path.isfile(AYAR_DOSYASI):
            return
        with open(AYAR_DOSYASI, "r", encoding="utf-8") as f:
            data = json.load(f)
        q = str(data.get("magic_fx_quality", v38_magic_fx_quality)).lower()
        p = str(data.get("combat_precision", v38_combat_precision)).lower()
        if q in V38_MAGIC_FX_QUALITIES:
            v38_magic_fx_quality = q
        if p in V38_COMBAT_PRECISIONS:
            v38_combat_precision = p
        v38_fire_self_damage = bool(data.get("fire_self_damage", v38_fire_self_damage))
        v38_impact_pause = bool(data.get("impact_pause", v38_impact_pause))
    except (
        OSError,
        ValueError,
        TypeError,
        json.JSONDecodeError,
    ):


        pass
