def ayar_kategorileri():
    result = []
    for kategori, items in _v38_ayar_kategorileri_original():
        items = list(items)
        if kategori == "goruntu" and "magic_fx_quality" not in items:
            items.append("magic_fx_quality")
        if kategori == "oynanis":
            for key in (
                "combat_precision",
                "fire_self_damage",
                "impact_pause",
            ):
                if key not in items:
                    items.append(key)
        result.append((kategori, items))
    return result


