def ayar_degeri(ayar):
    if ayar == "magic_fx_quality":
        names = {
            "low": bt("DÜŞÜK", "LOW"),
            "balanced": bt("DENGELİ", "BALANCED"),
            "high": bt("YÜKSEK", "HIGH"),
        }
        return names.get(v38_magic_fx_quality, names["balanced"])
    if ayar == "combat_precision":
        return (
            bt("SIKI", "STRICT")
            if v38_combat_precision == "strict"
            else bt("STANDART", "STANDARD")
        )
    if ayar == "fire_self_damage":
        return acik_kapali(v38_fire_self_damage)
    if ayar == "impact_pause":
        return acik_kapali(v38_impact_pause)
    return _v38_ayar_degeri_original(ayar)


def ayari_degistir(yon):
    global v38_magic_fx_quality, v38_combat_precision
    global v38_fire_self_damage, v38_impact_pause
    secenekler = ayar_secenekleri()
    if not secenekler:
        return
    ayar = secenekler[max(0, min(len(secenekler) - 1, ayar_index))]
    if ayar == "magic_fx_quality":
        v38_magic_fx_quality = dongulu_deger(
            list(V38_MAGIC_FX_QUALITIES),
            v38_magic_fx_quality,
            yon,
        )
    elif ayar == "combat_precision":
        v38_combat_precision = dongulu_deger(
            list(V38_COMBAT_PRECISIONS),
            v38_combat_precision,
            yon,
        )
    elif ayar == "fire_self_damage":
        v38_fire_self_damage = not v38_fire_self_damage
    elif ayar == "impact_pause":
        v38_impact_pause = not v38_impact_pause
    else:
        return _v38_ayari_degistir_original(yon)
    button_click_sesi_cal("menu1")
    ayarlari_kaydet()
