def fire_magic_kullan():
    """Normal Sphaera mana harcar, yalnız küçük bir casting stamina maliyeti bırakır.

    Eski fonksiyon stamina'yı 0'a indiriyordu. Burada önceki stamina snapshot'ı korunur,
    başarılı normal cast'ten sonra yalnız 10 stamina alınır. Ctrl+O bedelsiz test modu
    mana/stamina/cooldown üzerinde yine hiçbir etki yapmaz.
    """
    global oyuncu_stamina, stamina_son_harcama
    before = float(oyuncu_stamina)
    debug_free = bool(gelistirici_sonsuz_ates)
    ok = _v38_fire_magic_kullan_original()
    if not ok:
        return False
    if debug_free:
        oyuncu_stamina = before
    else:
        oyuncu_stamina = max(0.0, before - V38_FIRE_CAST_STAMINA_COST)
        stamina_son_harcama = pygame.time.get_ticks()
    return True





def fire_magic_patlama_hasari_uygula(x, y, simdi, direction=None):
    global oyuncu_hp
    center = pygame.Vector2(float(x), float(y))
    momentum = pygame.Vector2(direction or (0.0, 0.0))
    results = []

    for record in _fire_magic_hedef_kaydi():
        pos = pygame.Vector2(record["pos"])
        effective, geometric = _v38_effective_distance(center, pos, record["radius"])
        if effective > V38_FIRE_DAMAGE_RADIUS and geometric > V38_FIRE_THERMAL_RADIUS:
            continue
        exposure = _v38_exposure_fraction(center, pos, record["radius"])
        if exposure <= 0.0:
            continue

        if record["kind"] == "player":

            damage = _v38_self_damage_at(effective, exposure)
            knock = 0.0
            if effective <= V38_FIRE_SELF_KNOCKBACK_RADIUS and v38_fire_self_damage:
                knock = _v38_knockback_at(effective, exposure) * 0.42
            burn = _v38_self_burn_at(effective, exposure)

            actual = min(max(0, int(damage)), max(0, int(oyuncu_hp)))
            if actual > 0:
                oyuncu_hp = max(0, int(oyuncu_hp) - actual)
                profile = "magic_heavy" if effective < 54.0 else "medium_blunt"
                source = (
                    "fire_magic_self_core"
                    if effective < 54.0
                    else "fire_magic_self_heat"
                )
                oyuncu_kanli_hasar_kaydi(center.x, center.y, profile, actual, source)
                dunya_olayi_kaydet(
                    "hit_taken",
                    damage=actual,
                    count=1,
                    enemy=source,
                    self_hit=True,
                    distance=round(float(effective), 2),
                    exposure=round(float(exposure), 3),
                )
            if knock > 20.0:
                _fire_magic_player_impulse_uygula(center, knock, simdi)
            if oyuncu_hp > 0 and burn > 0:
                _fire_magic_burn_player_uygula(burn, simdi)
            if actual > 0 or knock > 20.0 or burn > 0:
                results.append(("player", actual, geometric, "continuous"))
            continue

        enemy = record["obj"]
        damage = _v38_enemy_damage_at(effective, exposure)
        burn = _v38_burn_total_at(effective, exposure)
        knock = _v38_knockback_at(effective, exposure)
        hp_before = max(0, int(getattr(enemy, "hp", 0)))
        if hp_before <= 0:
            continue



        direct = int(damage)
        if effective > 118.0 and direct >= hp_before:
            direct = max(0, hp_before - 1)
        if direct > 0:
            profile = "magic_heavy" if effective < 72.0 else "medium_blunt"
            source = _V30FireDamageSource(center.x, center.y, profile)
            enemy.hasar_al(direct, kaynak=source)
        actual = max(0, hp_before - int(getattr(enemy, "hp", 0)))

        if knock > 20.0 and getattr(enemy, "active", False):
            _fire_magic_enemy_impulse_uygula(enemy, center, knock, simdi)
        if (
            burn > 0
            and getattr(enemy, "active", False)
            and int(getattr(enemy, "hp", 0)) > 0
        ):
            _fire_magic_burn_enemy_uygula(enemy, burn, simdi)


        if hp_before > 0 and int(getattr(enemy, "hp", 0)) <= 0 and effective < 82.0:
            pseudo_shell = 675 if effective < 44.0 else 425
            _v33_enemy_blast_extra_gore(enemy, pseudo_shell, center)

        dunya_olayi_kaydet(
            "fire_magic_hit",
            target=str(getattr(enemy, "uid", getattr(enemy, "tur", "enemy"))),
            damage=actual,
            distance=round(float(effective), 2),
            exposure=round(float(exposure), 3),
            pressure=round(float(_v38_pressure_field(effective)), 4),
            thermal=round(float(_v38_thermal_field(effective)), 4),
        )
        results.append(
            (
                str(getattr(enemy, "uid", "enemy")),
                actual,
                geometric,
                "continuous",
            )
        )

    return results
