def _v38_fire_projectile_explode(self, simdi):
    if not self.active:
        return
    self.active = False
    player_magic_explosions.append(
        FireMagicExplosion(
            self.x,
            self.y,
            simdi,
            self.direction,
            source_travel=self.travelled,
            source_origin=self.start,
            source_temperature=self.temperature_k,
        )
    )


def _v38_fire_projectile_update(self, dt, simdi):
    if not self.active:
        return
    age_ms = max(0, int(simdi) - int(self.start_ms))
    age_s = age_ms / 1000.0
    if (
        age_ms >= V38_FIRE_PROJECTILE_TTL_MS
        or self.travelled >= V38_FIRE_PROJECTILE_MAX_TRAVEL
        or self._dunya_disinda_mi()
    ):
        self.active = False
        return

    self.speed = _v38_projectile_speed(age_s)
    self.temperature_k = _v38_projectile_temperature(age_s)
    self.v = self.direction * self.speed
    total = max(0.0, self.speed * max(0.0, float(dt)))
    remaining = total
    step_limit = max(2.0, float(V38_FIRE_PROJECTILE_COLLISION_STEP))

    while remaining > 1e-6 and self.active:
        step = min(step_limit, remaining)
        old = pygame.Vector2(self.x, self.y)
        new = old + self.direction * step

        if harita_pikseli_engel_mi(new.x, new.y):
            self.x, self.y = old.x, old.y
            _v38_fire_projectile_explode(self, simdi)
            break

        hit = None

        for enemy in _magic_hedefleri():
            radius = _magic_hedef_yaricapi(enemy) + V38_FIRE_PROJECTILE_RADIUS
            target = pygame.Vector2(float(enemy.x), float(enemy.y) - 7.0)
            if new.distance_to(target) <= radius:
                hit = enemy
                break

        self.x, self.y = new.x, new.y
        self.travelled += step
        remaining -= step

        if hit is not None:
            _v38_fire_projectile_explode(self, simdi)
            break


def _v38_fire_projectile_draw(self):
    if not self.active or not FIRE_MAGIC_PROJECTILE_SPRITELERI:
        return
    sx = dunya_ekran_x(self.x)
    sy = dunya_ekran_y(self.y)
    now = pygame.time.get_ticks()
    age = max(0, now - self.anim_epoch)
    if len(FIRE_MAGIC_PROJECTILE_SPRITELERI) >= 3:
        idx = 0 if age < 50 else 1 if age < 105 else 2
    else:
        idx = min(len(FIRE_MAGIC_PROJECTILE_SPRITELERI) - 1, age // 65)
    frame = FIRE_MAGIC_PROJECTILE_SPRITELERI[idx]
    direction_name = (
        "left"
        if self.direction.x < -0.5
        else "right"
        if self.direction.x > 0.5
        else "up"
        if self.direction.y < 0.0
        else "down"
    )

    temp_ratio = _v38_clamp01(
        (self.temperature_k - V38_FIRE_MIN_VISIBLE_TEMPERATURE_K)
        / max(
            1.0,
            V38_FIRE_CORE_TEMPERATURE_K - V38_FIRE_MIN_VISIBLE_TEMPERATURE_K,
        )
    )
    thermal_scale = 0.88 + 0.16 * temp_ratio
    h = int(
        round(
            56
            * FIRE_MAGIC_PROJECTILE_VISUAL_SCALE
            * thermal_scale
            * KAMERA_YAKINLASTIRMA
        )
    )
    img = _v38_oriented_fire_sprite(frame, h, direction_name, 255)


    intensity = _v38_blackbody_visual_intensity(self.temperature_k)
    glow_r = int(round((16 + 7 * intensity) * KAMERA_YAKINLASTIRMA))
    glow = _v38_glow_surface(glow_r, int(round(intensity * 10)))
    ekran.blit(
        glow,
        glow.get_rect(center=(sx, sy - 12)),
        special_flags=pygame.BLEND_RGBA_ADD,
    )


    density = _v38_fx_density()
    ghosts = 1 if density < 0.8 else 2 if density < 1.2 else 3
    for i in range(ghosts, 0, -1):
        offset = 15.0 + i * 14.0
        alpha = int(26 + 26 * (ghosts - i + 1) / ghosts)
        ghost = _v38_oriented_fire_sprite(frame, h, direction_name, alpha)
        px = sx - self.direction.x * offset * KAMERA_YAKINLASTIRMA
        py = sy - 12 - self.direction.y * offset * KAMERA_YAKINLASTIRMA
        ekran.blit(ghost, ghost.get_rect(center=(int(px), int(py))))
    ekran.blit(img, img.get_rect(center=(sx, sy - 12)))
