def _v38_fire_contract():
    distances = [
        0.0,
        30.0,
        60.0,
        90.0,
        120.0,
        150.0,
        180.0,
        214.0,
    ]
    enemy = [_v38_enemy_damage_at(d, 1.0) for d in distances]
    selfd = [_v38_self_damage_at(d, 1.0) for d in distances]
    pressure = [_v38_pressure_field(d) for d in distances]
    thermal = [_v38_thermal_field(d) for d in distances]
    return {
        "enemy_damage_monotonic": _v38_monotonic_nonincreasing(enemy),
        "self_damage_monotonic": _v38_monotonic_nonincreasing(selfd),
        "pressure_monotonic": _v38_monotonic_nonincreasing(pressure),
        "thermal_monotonic": _v38_monotonic_nonincreasing(thermal),
        "self_zero_far": _v38_self_damage_at(V38_FIRE_SELF_DAMAGE_RADIUS + 8.0, 1.0)
        == 0,
        "enemy_zero_far": _v38_enemy_damage_at(V38_FIRE_DAMAGE_RADIUS + 8.0, 1.0) == 0,
        "projectile_range_finite": 500.0 < V38_FIRE_PROJECTILE_MAX_TRAVEL < 1800.0,
        "cast_release_before_total": FIRE_MAGIC_CAST_RELEASE_MS
        < FIRE_MAGIC_CAST_TOTAL_MS,
    }
