def v38_cross_system_invariants():
    """Magic/combat/special değerlerinin birbirleriyle çelişmediğini denetler."""
    nr, nw, hr, hw = _v38_player_reach_values()
    return {
        "fire_self_radius_inside_enemy_radius": (
            V38_FIRE_SELF_DAMAGE_RADIUS < V38_FIRE_DAMAGE_RADIUS
        ),
        "fire_self_burn_inside_self_damage": (
            V38_FIRE_SELF_BURN_RADIUS < V38_FIRE_SELF_DAMAGE_RADIUS
        ),
        "fire_thermal_inside_damage_or_close": (
            V38_FIRE_THERMAL_RADIUS <= V38_FIRE_DAMAGE_RADIUS
        ),
        "fire_vinf_not_faster_than_v0": (
            V38_FIRE_PROJECTILE_VINF <= V38_FIRE_PROJECTILE_V0
        ),
        "fire_release_before_lock_end": (
            FIRE_MAGIC_CAST_RELEASE_MS <= FIRE_MAGIC_CAST_LOCK_MS
        ),
        "fire_lock_before_total_or_close": (
            FIRE_MAGIC_CAST_LOCK_MS <= FIRE_MAGIC_CAST_TOTAL_MS
        ),
        "fire_ground_smaller_than_blast": (
            FIRE_MAGIC_GROUND_FIRE_RADIUS < V38_FIRE_DAMAGE_RADIUS
        ),
        "player_normal_narrower_than_heavy": (nr < hr and nw < hw),
        "player_heavy_local_smaller_than_body_lunge": (hr < ADEFO_HOLD_DASH_MESAFESI),
        "special_three_hits_fit_default_stamina": (V38_SPECIAL_TOTAL_STAMINA <= 100.0),
        "special_cost_is_three_equal_steps": (
            abs(V38_SPECIAL_TOTAL_STAMINA - 3.0 * V38_SPECIAL_STAMINA_PER_HIT) < 1e-6
        ),
        "special_faster_than_old_v35": (GELISTIRICI_X_SKILL_SURE_MS < 1660),
        "strict_enemy_active_less_than_startup": all(
            V38_ENEMY_ACTIVE_ROOT_STRICT[k] < V38_ENEMY_START_ROOT[k]
            for k in V38_ENEMY_ACTIVE_ROOT_STRICT
        ),
        "standard_enemy_active_less_than_startup": all(
            V38_ENEMY_ACTIVE_ROOT_STANDARD[k] < V38_ENEMY_START_ROOT[k]
            for k in V38_ENEMY_ACTIVE_ROOT_STANDARD
        ),
        "strict_not_more_permissive_than_standard": all(
            V38_ENEMY_ACTIVE_ROOT_STRICT[k] <= V38_ENEMY_ACTIVE_ROOT_STANDARD[k]
            for k in V38_ENEMY_ACTIVE_ROOT_STRICT
        ),
        "fx_quality_valid": v38_magic_fx_quality in V38_MAGIC_FX_QUALITIES,
        "combat_precision_valid": v38_combat_precision in V38_COMBAT_PRECISIONS,
        "ground_fire_budget_finite": 0 < V38_MAX_GROUND_FIRES <= 120,
        "projectile_budget_finite": 0 < V38_MAX_PROJECTILES <= 12,
        "explosion_budget_finite": 0 < V38_MAX_EXPLOSIONS <= 8,
    }
