def _v39_fire_projectile_draw(self):
    if not self.active or not FIRE_MAGIC_PROJECTILE_SPRITELERI:
        return
    sx = dunya_ekran_x(self.x)
    sy = dunya_ekran_y(self.y)
    now = pygame.time.get_ticks()
    age = max(0, now - self.anim_epoch)
    if len(FIRE_MAGIC_PROJECTILE_SPRITELERI) >= 3:
        idx = 0 if age < 50 else 1 if age < 105 else 2
    else:
        idx = min(len(FIRE_MAGIC_PROJECTILE_SPRITELERI) - 1, age // 65)
    frame = FIRE_MAGIC_PROJECTILE_SPRITELERI[idx]
    direction_name = (
        "left"
        if self.direction.x < -0.5
        else "right"
        if self.direction.x > 0.5
        else "up"
        if self.direction.y < 0.0
        else "down"
    )
    temp_ratio = v39_clamp01(
        (self.temperature_k - V38_FIRE_MIN_VISIBLE_TEMPERATURE_K)
        / max(
            1.0,
            V38_FIRE_CORE_TEMPERATURE_K - V38_FIRE_MIN_VISIBLE_TEMPERATURE_K,
        )
    )
    thermal_scale = 0.90 + 0.17 * temp_ratio
    h = int(
        round(
            56
            * FIRE_MAGIC_PROJECTILE_VISUAL_SCALE
            * thermal_scale
            * KAMERA_YAKINLASTIRMA
        )
    )
    img = _v38_oriented_fire_sprite(frame, h, direction_name, 255)
    intensity = _v38_blackbody_visual_intensity(self.temperature_k)
    glow_r = int(round((17 + 8 * intensity) * KAMERA_YAKINLASTIRMA))
    glow = _v38_glow_surface(glow_r, int(round(intensity * 10)))
    phase = int((now - self.start_ms) / 45) % 4
    detail = _v39_fireball_detail_surface(
        max(7, glow_r),
        min(4, int((1.0 - temp_ratio) * 4.999)),
        direction_name,
        phase,
    )
    ekran.blit(
        detail,
        detail.get_rect(center=(sx, sy - 12)),
        special_flags=pygame.BLEND_RGBA_ADD,
    )
    ekran.blit(
        glow,
        glow.get_rect(center=(sx, sy - 12)),
        special_flags=pygame.BLEND_RGBA_ADD,
    )
    density = _v38_fx_density()
    ghosts = 1 if density < 0.8 else 2
    for i in range(ghosts, 0, -1):
        offset = 13.0 + i * 13.0
        alpha = int(24 + 22 * (ghosts - i + 1) / ghosts)
        ghost = _v38_oriented_fire_sprite(frame, h, direction_name, alpha)
        px = sx - self.direction.x * offset * KAMERA_YAKINLASTIRMA
        py = sy - 12 - self.direction.y * offset * KAMERA_YAKINLASTIRMA
        ekran.blit(ghost, ghost.get_rect(center=(int(px), int(py))))
    ekran.blit(img, img.get_rect(center=(sx, sy - 12)))
    accent = _v39_blackbody_rgb(self.temperature_k)
    pygame.draw.circle(
        ekran,
        accent,
        (int(sx), int(sy - 12)),
        max(1, int(2 * KAMERA_YAKINLASTIRMA)),
    )
