def gore_olum_patlamasi(x, y, profil="slash", yon=None):
    result = _v73_gore_death_original(x, y, profil, yon=yon)
    profile = str(profil or "slash")
    if profile in ("heavy_slash", "heavy_blunt", "magic_heavy"):
        extra = random.randint(3, 5)
        speed_range = (118.0, 238.0)
    elif profile in ("medium_slash", "medium_blunt"):
        extra = random.randint(2, 4)
        speed_range = (82.0, 178.0)
    else:
        extra = random.randint(1, 2)
        speed_range = (62.0, 132.0)

    kinds = [
        k
        for k in (
            "flesh_shard_a",
            "flesh_shard_b",
            "organ_round_a",
            "organ_round_b",
            "liver",
            "intestine",
        )
        if k in GORE_SPRITELERI
    ]
    if not kinds:
        return result

    base = v73_safe_direction(
        yon
        if yon is not None
        else pygame.Vector2(1.0, 0.0).rotate(random.uniform(0, 360))
    )
    for _ in range(extra):
        chunk = GoreChunk(
            random.choice(kinds),
            x,
            y,
            guc=random.uniform(0.82, 1.10),
            small=True,
        )
        d = base.rotate(random.uniform(-74.0, 74.0))
        if random.random() < 0.16:
            d *= -1.0
        d = v73_safe_direction(d)
        chunk.v = d * random.uniform(*speed_range)
        chunk.vz = random.uniform(92.0, 206.0)
        chunk.angular = random.uniform(-520.0, 520.0)
        gore_chunks.append(chunk)
    return result
