def v73_blast_source_tier(kaynak_adi, profil=""):
    source = str(kaynak_adi or "").strip().lower()
    profile = str(profil or "").strip().lower()
    if not source:
        return None

    if source in ("fire_magic_burn", "ground_fire") or (
        "burn" in source and "explosion" not in source and "bomb" not in source
    ):
        return None

    core_exact = {
        "fire_magic_explosion_core",
        "fire_magic_self_core",
        "blast_core",
        "bomb_core",
        "grenade_core",
    }
    inner_exact = {
        "fire_magic_explosion_inner",
        "fire_magic_explosion_mid",
        "fire_magic_explosion_shock",
        "fire_magic_self_heat",
        "blast_inner",
        "bomb_inner",
        "grenade_inner",
    }
    if source in core_exact:
        return "core"
    if source in inner_exact:
        return "inner"
    if any(
        token in source
        for token in (
            "bomb",
            "bomba",
            "grenade",
            "explosive",
            "explosion",
            "patlama",
            "blast",
        )
    ):
        if any(
            token in source
            for token in (
                "inner",
                "mid",
                "heat",
                "shock",
                "edge",
                "outer",
            )
        ):
            return "inner"
        return "core" if profile in ("magic_heavy", "heavy_blunt") else "inner"
    return None
