def v84_direct_melee_source(source_type, source_x, source_y, attacker):
    if attacker is None:
        return False
    if not bool(getattr(attacker, "active", False)):
        return False
    if int(getattr(attacker, "hp", 0)) <= 0:
        return False
    source_name = str(source_type or "").lower()
    actor_name = str(getattr(attacker, "tur", "")).lower()
    if source_name in {
        "ground_fire",
        "fire",
        "burn",
        "fire_magic",
        "fire_magic_explosion",
        "headsthrower_rock",
        "rock",
        "blast",
        "shockwave",
    }:
        return False
    if actor_name and source_name and source_name != actor_name:
        aliases = {
            ("headsthrower", "headsthrower_melee"),
            ("torrmund", "heavy_slash"),
            ("tarkard", "heavy_blunt"),
        }
        if (actor_name, source_name) not in aliases:
            return False
    distance = pygame.Vector2(
        float(source_x),
        float(source_y),
    ).distance_to((oyuncu_x, oyuncu_y))
    reach = float(
        getattr(
            attacker,
            "cfg",
            {},
        ).get("attack_range", 112.0)
    )
    return distance <= max(138.0, reach + 48.0)
