def oyuncu_kanli_hasar_kaydi(
    kaynak_x,
    kaynak_y,
    profil,
    hasar,
    kaynak_adi="",
):
    global oyuncu_hp
    if v85_forcing_final_hit:
        return _v85_player_damage_original(
            kaynak_x, kaynak_y, profil, hasar, kaynak_adi
        )
    if v85_mortal_wound_state.active:



        oyuncu_hp = 1
        return 0

    killer = v85_direct_killer(kaynak_x, kaynak_y, kaynak_adi)
    profile = str(profil or "slash")
    delayed = (
        oyuncu_hp <= 0
        and killer is not None
        and profile
        not in (
            "burn",
            "fire_burn",
            "magic_burn",
            "magic_heavy",
        )
        and v73_blast_source_tier(kaynak_adi, profil) is None
    )
    if not delayed:
        return _v85_player_damage_original(
            kaynak_x, kaynak_y, profil, hasar, kaynak_adi
        )



    actual_damage = max(1, int(hasar))
    oyuncu_hp = actual_damage + 2
    result = _v85_player_damage_original(kaynak_x, kaynak_y, profil, hasar, kaynak_adi)
    oyuncu_hp = 1
    v85_mortal_wound_start(
        killer,
        kaynak_x,
        kaynak_y,
        profil,
        actual_damage,
        kaynak_adi,
    )
    return result
