def v85_death_variant(profile, death_type, alternate, seed):
    profile = str(profile or "slash")
    death_type = str(death_type or "blood")
    alternate = str(alternate or "")
    rng = random.Random(int(seed) ^ 0xD15E85)
    if death_type == "fire":
        return "fire"
    if death_type == "blast_core":
        return "shatter"
    if death_type == "blast_inner":
        return "torso" if rng.random() < 0.58 else "minor"
    if "decap" in alternate or alternate == "headshot":
        return "decap"
    if "bisect" in alternate:
        return "bisect"
    if alternate == "tarkard_crush":
        return "torso" if rng.random() < 0.74 else "shatter"
    roll = rng.random()
    if profile == "heavy_slash":
        if roll < 0.34:
            return "bisect"
        if roll < 0.46:
            return "shatter"
        return "minor"
    if profile in ("heavy_blunt", "magic_heavy"):
        if roll < 0.16:
            return "shatter"
        if roll < 0.39:
            return "torso"
        return "minor"
    if profile == "medium_slash" and roll < 0.09:
        return "bisect"
    return "minor"
