def v87_ground_fire_frames_from_embedded():
    try:
        import base64
        import io

        raw = base64.b64decode(V87_GROUND_FIRE_ATLAS_BASE64, validate=True)
        sheet = pygame.image.load(
            io.BytesIO(raw), "sphaera_exothermica_ground_fire.png"
        ).convert_alpha()
    except (ImportError, TypeError, ValueError, pygame.error):
        return []

    if sheet.get_size() != (155, 145):
        return []
    sheet = _sinir_baglantili_fon_temizle(sheet, (255, 255, 255), 7)
    frames = []
    for x, y, width, height in FIRE_MAGIC_GROUND_RECTLERI:
        area = pygame.Rect(x, y, width, height).clip(sheet.get_rect())
        if area.width <= 0 or area.height <= 0:
            continue
        frame = sheet.subsurface(area).copy().convert_alpha()
        bounds = frame.get_bounding_rect(min_alpha=1)
        if bounds.width <= 0 or bounds.height <= 0:
            continue
        bounds = bounds.inflate(2, 2).clip(frame.get_rect())
        frames.append(frame.subsurface(bounds).copy().convert_alpha())
    return frames
