def v87_death_fire_sprite(height, seed, alpha=244):
    frames = V87_GROUND_FIRE_SPRITES or FIRE_MAGIC_GROUND_SPRITELERI
    if not frames:
        return None
    frame = frames[abs(int(seed)) % len(frames)]
    height = max(5, int(round(height)))
    alpha = max(0, min(255, int(alpha)))
    key = (id(frame), height, alpha)
    cached = v87_death_fire_cache.get(key)
    if cached is not None:
        return cached
    ratio = frame.get_width() / max(1.0, float(frame.get_height()))
    source = pygame.transform.scale(
        frame,
        (max(2, int(round(height * ratio))), height),
    )
    mask = pygame.mask.from_surface(source, 6)
    image = mask.to_surface(
        setcolor=(*V84_BODY, alpha),
        unsetcolor=(0, 0, 0, 0),
    ).convert_alpha()
    if len(v87_death_fire_cache) >= 192:
        for old_key in list(v87_death_fire_cache)[:48]:
            v87_death_fire_cache.pop(old_key, None)
    v87_death_fire_cache[key] = image
    return image
