def _v89_ground_fire_draw(self):
    frames = V89_GROUND_FIRE_FRAMES or FIRE_MAGIC_GROUND_SPRITELERI
    if not getattr(self, "active", False) or not frames:
        return
    now = pygame.time.get_ticks()
    age = v89_clamp01(
        (now - int(self.start_ms)) / max(1.0, float(getattr(self, "duration_ms", 1)))
    )
    fade_in = min(1.0, age / 0.10)
    fade_out = 1.0 if age < 0.74 else max(0.0, (1.0 - age) / 0.26)
    alpha = max(0, min(255, int(round(255 * fade_in * fade_out))))
    if alpha <= 0:
        return
    frame = frames[int(getattr(self, "v89_frame_index", 0)) % len(frames)]
    pulse_bucket = (now // 92 + int(getattr(self, "v89_pulse_phase", 0))) % 5
    pulse = (0.97, 1.00, 1.035, 1.00, 0.985)[pulse_bucket]
    height = max(
        9,
        int(
            round(
                frame.get_height()
                * float(getattr(self, "scale", 1.0))
                * pulse
                * float(KAMERA_YAKINLASTIRMA)
            )
        ),
    )
    ratio = frame.get_width() / max(1.0, float(frame.get_height()))
    size = (max(2, int(round(height * ratio))), height)
    key = (id(frame), size, bool(getattr(self, "v89_flip", False)))
    image = v89_ground_fire_cache.get(key)
    if image is None:
        image = pygame.transform.scale(frame, size).convert_alpha()
        if getattr(self, "v89_flip", False):
            image = pygame.transform.flip(image, True, False)
        if len(v89_ground_fire_cache) >= 192:
            for old_key in list(v89_ground_fire_cache)[:48]:
                v89_ground_fire_cache.pop(old_key, None)
        v89_ground_fire_cache[key] = image
    draw = image
    if alpha < 248:
        draw = image.copy()
        draw.set_alpha(alpha)
    position = (dunya_ekran_x(self.x), dunya_ekran_y(self.y) + 3)
    ekran.blit(draw, draw.get_rect(midbottom=position))
