def v87_death_fire_sprite(height, seed, alpha=244):
    frames = V89_SMALL_FIRE_FRAMES
    if not frames:
        frames = V89_GROUND_FIRE_FRAMES or FIRE_MAGIC_GROUND_SPRITELERI
    if not frames:
        return None
    frame = frames[(abs(int(seed)) + pygame.time.get_ticks() // 92) % len(frames)]
    height = max(5, int(round(height)))
    alpha_bucket = max(0, min(255, int(round(int(alpha) / 16.0)) * 16))
    ratio = frame.get_width() / max(1.0, float(frame.get_height()))
    size = (max(2, int(round(height * ratio))), height)
    key = (id(frame), size, alpha_bucket)
