def v90_segment_target(start, end):
    start = pygame.Vector2(start)
    end = pygame.Vector2(end)
    segment = end - start
    length2 = segment.length_squared()
    best = None
    best_t = 2.0
    for actor in v90_hostiles():
        center = v90_actor_center(actor)
        if length2 <= 1e-8:
            t_value = 0.0
            nearest = start
        else:
            t_value = v90_clamp((center - start).dot(segment) / length2)
            nearest = start + segment * t_value
        radius = max(17.0, _magic_hedef_yaricapi(actor) + 14.0)
        if center.distance_squared_to(nearest) <= radius * radius and t_value < best_t:
            best = actor
            best_t = t_value
    return best
# </POTBO_STAGE S2175>

# <POTBO_STAGE S2178>


def v90_calcinatio_apply_tick(status, now):
    if not v90_actor_alive(status.actor):
        return
    center = v90_actor_center(status.actor)
    source = V90MagicSource(center.x, center.y, "calcinatio")
    _v90_enemy_damage_raw(status.actor, 4, source)
    v90_spawn_embers(center, 4, status.seed ^ int(now), pygame.Vector2(0.0, -12.0))
    v90_draco_stats["calcinatio_ticks"] += 1


def v90_calcinatio_update(now, dt):
    for uid, status in list(v90_calcinatio.items()):
        if (
            int(now) >= int(status.expires_ms)
            or not v90_actor_alive(status.actor)
            or v84_actor_uid(status.actor) != status.actor_uid
        ):
            v90_calcinatio.pop(uid, None)
            continue
        current = v90_actor_center(status.actor)
        moved = current.distance_to(status.last_position)
        if moved >= 2.2 and int(now) >= int(status.next_motion_ember_ms):
            status.next_motion_ember_ms = int(now) + 105
            status.last_position = current
            v90_spawn_embers(
                current + pygame.Vector2(0.0, 8.0),
                2,
                status.seed ^ int(now),
                pygame.Vector2(0.0, 5.0),
            )
        elif moved > 0.1:
            status.last_position = current
        while int(now) >= int(status.next_tick_ms):
            status.next_tick_ms += V90_CALCINATIO_TICK_MS
            v90_calcinatio_apply_tick(status, now)

    for ember in v90_embers:
        ember.update(dt)
    v90_embers[:] = [ember for ember in v90_embers if ember.alive(now)]
    v90_ash_marks[:] = [mark for mark in v90_ash_marks if mark.alive(now)]




_v90_enemy_damage_raw = CommonEnemy.hasar_al


def _v90_enemy_damage(self, miktar, kaynak=None):
    before = int(getattr(self, "hp", 0))
    result = _v90_enemy_damage_raw(self, miktar, kaynak)
    actual = max(0, before - int(getattr(self, "hp", 0)))
    uid = v84_actor_uid(self)
    status = v90_calcinatio.get(uid)
    source_is_magic = bool(getattr(kaynak, "is_player_magic", False))
    source_is_player_physical = kaynak is None or kaynak == "player"
    now = pygame.time.get_ticks()
    if (
        actual > 0
        and status is not None
        and source_is_player_physical
        and not source_is_magic
        and int(now) >= int(status.next_physical_ms)
        and v90_actor_alive(self)
    ):
        status.next_physical_ms = int(now) + V90_CALCINATIO_PHYSICAL_TRIGGER_MS
        bonus = max(3, min(11, int(round(actual * 0.20))))
        center = v90_actor_center(self)
        _v90_enemy_damage_raw(
            self,
            bonus,
            V90MagicSource(center.x, center.y, "calcinatio_rupture"),
        )
        v90_spawn_embers(
            center,
            7,
            status.seed ^ int(now) ^ actual,
            pygame.Vector2(0.0, -16.0),
        )
        v90_draco_stats["physical_triggers"] += 1
    return result
