def kan_gore_guncelle():
    global _v90_last_world_tick_ms
    result = _v90_blood_world_update_raw()
    now = pygame.time.get_ticks()
    raw_gap = max(0, int(now) - int(_v90_last_world_tick_ms))


    pause_compensation = max(0, raw_gap - 80)
    if pause_compensation > 0:
        if v90_draco_state.active:
            v90_draco_state.phase_started_ms += pause_compensation
            v90_draco_state.cast_started_ms += pause_compensation
            v90_draco_state.last_trail_ms += pause_compensation
            v90_draco_state.next_scorch_ms += pause_compensation
            v90_draco_state.trail = deque(
                (
                    (
                        position,
                        frame_index,
                        born + pause_compensation,
                    )
                    for position, frame_index, born in v90_draco_state.trail
                ),
                maxlen=10,
            )
        for status in v90_calcinatio.values():
            status.started_ms += pause_compensation
            status.expires_ms += pause_compensation
            status.next_tick_ms += pause_compensation
            status.next_physical_ms += pause_compensation
            status.next_motion_ember_ms += pause_compensation
        for ember in v90_embers:
            ember.born_ms += pause_compensation
        if v90_injury.next_bleed_ms > 0:
            v90_injury.next_bleed_ms += pause_compensation
        if v90_injury.next_rivulet_ms > 0:
            v90_injury.next_rivulet_ms += pause_compensation
    dt = max(0.0, min(0.05, raw_gap / 1000.0))
    _v90_last_world_tick_ms = int(now)
    if oyun_durumu == OYUN and oyun_alt_durumu == HARITA:
        v90_injury_update(now, dt)
        v90_draco_state.update(now)
        v90_calcinatio_update(now, dt)
    else:
        return result
    return result
