def oyun_yukle(*args, **kwargs):
    result = _v90_load_game_raw(*args, **kwargs)
    if not result:
        return result
    v90_draco_state.reset()
    v90_calcinatio.clear()
    v90_embers.clear()
    v90_ash_marks.clear()
    path = args[0] if args else kwargs.get("dosya_yolu")
    try:
        with open(path, "r", encoding="utf-8") as source:
            payload = json.load(source)
        v90_injury_restore(payload.get(V90_INJURY_SAVE_KEY, {}))
    except (OSError, ValueError, TypeError):
        v90_injury.reset()
        v90_injury_recalculate()
    return result
