def gelistirici_test_girdisi_uygula(olay):
    global oyuncu_altin, v91_test_panel_visible
    if not GELISTIRICI_MODU or olay.type != pygame.KEYDOWN:
        return False
    if olay.key == pygame.K_QUOTE:
        v91_test_panel_visible = not v91_test_panel_visible
        bildirim_goster(
            bt(
                "Test arayüzü AÇIK."
                if v91_test_panel_visible
                else "Test arayüzü KAPALI.",
                "Test overlay ON."
                if v91_test_panel_visible
                else "Test overlay OFF.",
            ),
            V91_UI_WHITE,
        )
        return True
    if olay.mod & pygame.KMOD_CTRL:
        if olay.key == pygame.K_i:
            oyuncu_altin += 1000
            bildirim_goster(bt("+1000 altın", "+1000 gold"), V91_UI_GOLD)
            return True
        if olay.key == pygame.K_1:
            return bool(v91_grant_and_bind_spell("fire_magic"))
        if olay.key == pygame.K_2:
            return bool(v91_grant_and_bind_spell("draco_calcinans"))
    return _v91_dev_input_raw(olay)


