def _v91_fire_projectile_draw(self):
    if not self.active or not FIRE_MAGIC_PROJECTILE_SPRITELERI:
        return
    sx = int(round(dunya_ekran_x(self.x)))
    sy = int(round(dunya_ekran_y(self.y) - 12))
    now = pygame.time.get_ticks()
    age = max(0, now - self.anim_epoch)
    idx = (
        0
        if age < 46
        else 1
        if age < 96
        else min(2, len(FIRE_MAGIC_PROJECTILE_SPRITELERI) - 1)
    )
    frame = FIRE_MAGIC_PROJECTILE_SPRITELERI[idx]
    direction_name = (
        "left"
        if self.direction.x < -0.5
        else "right"
        if self.direction.x > 0.5
        else "up"
        if self.direction.y < 0.0
        else "down"
    )
    temp_ratio = v39_clamp01(
        (self.temperature_k - V38_FIRE_MIN_VISIBLE_TEMPERATURE_K)
        / max(
            1.0,
            V38_FIRE_CORE_TEMPERATURE_K
            - V38_FIRE_MIN_VISIBLE_TEMPERATURE_K,
        )
    )
    height = int(
        round(
            64
            * FIRE_MAGIC_PROJECTILE_VISUAL_SCALE
            * (0.94 + temp_ratio * 0.10)
            * KAMERA_YAKINLASTIRMA
        )
    )
    draws = []

    for offset, alpha in ((70.0, 28), (48.0, 48), (28.0, 82)):
        ghost = _v38_oriented_fire_sprite(
            frame, height, direction_name, alpha
        )
        point = (
            pygame.Vector2(sx, sy)
            - self.direction * offset * KAMERA_YAKINLASTIRMA
        )
        draws.append(
            (ghost, ghost.get_rect(center=(int(point.x), int(point.y))))
        )
    if V89_SMALL_FIRE_FRAMES:
        tangent = pygame.Vector2(-self.direction.y, self.direction.x)
        for index in range(4):
            small = V89_SMALL_FIRE_FRAMES[
                (now // 82 + index * 2) % len(V89_SMALL_FIRE_FRAMES)
            ]
            image = v91_oriented_small_flame(
                small,
                (9 + index * 2) * KAMERA_YAKINLASTIRMA,
                direction_name,
                176 - index * 28,
            )
            point = (
                pygame.Vector2(sx, sy)
                - self.direction
                * (19.0 + index * 15.0)
                * KAMERA_YAKINLASTIRMA
                + tangent
                * math.sin(now * 0.025 + index * 1.9)
                * (2.0 + index)
            )
            draws.append(
                (image, image.get_rect(center=(int(point.x), int(point.y))))
            )
    if FIRE_MAGIC_ORB_SPRITELERI:
        orb_frame = FIRE_MAGIC_ORB_SPRITELERI[
            (now // 58) % len(FIRE_MAGIC_ORB_SPRITELERI)
        ]
        orb_h = max(12, int(round(height * 0.48)))
        orb = _v38_oriented_fire_sprite(
            orb_frame, orb_h, direction_name, 232
        )
        draws.append((orb, orb.get_rect(center=(sx, sy))))
    body = _v38_oriented_fire_sprite(
        frame, height, direction_name, 255
    )
    draws.append((body, body.get_rect(center=(sx, sy))))
    ekran.blits(draws)
