def _v91_fire_explosion_draw(self):
    if not self.active or not self.detonated:
        return
    now = pygame.time.get_ticks()
    ex = int(round(dunya_ekran_x(self.x)))
    ey = int(round(dunya_ekran_y(self.y)))
    age = max(0, now - int(self.explosion_start_ms))
    progress = _v38_clamp01(
        age / max(1.0, float(self.duration_ms))
    )
    if FIRE_MAGIC_EXPLOSION_SPRITELERI:
        timeline = _v38_smoothstep(min(1.0, progress / 0.92))
        index = min(
            len(FIRE_MAGIC_EXPLOSION_SPRITELERI) - 1,
            int(timeline * len(FIRE_MAGIC_EXPLOSION_SPRITELERI)),
        )
        frame = FIRE_MAGIC_EXPLOSION_SPRITELERI[index]
        height = int(
            round(
                132
                * FIRE_MAGIC_EXPLOSION_VISUAL_SCALE
                * (1.0 + 0.07 * math.sin(progress * math.pi))
                * KAMERA_YAKINLASTIRMA
            )
        )
        key = ("v91_explosion", id(frame), height)
        image = v38_fire_explosion_core_cache.get(key)
        if image is None:
            scale = height / max(1.0, float(frame.get_height()))
            image = pygame.transform.scale(
                frame,
                (
                    max(1, int(round(frame.get_width() * scale))),
                    height,
                ),
            ).convert_alpha()
            v38_fire_explosion_core_cache[key] = image
            _v38_cache_limit(v38_fire_explosion_core_cache, 112)
        ekran.blit(image, image.get_rect(midbottom=(ex, ey + 12)))
    cluster = v91_impact_flame_cluster(
        int(self.x * 31 + self.y * 47),
        progress,
        KAMERA_YAKINLASTIRMA,
    )
    if cluster is not None and progress < 0.86:
        ekran.blit(cluster, cluster.get_rect(midbottom=(ex, ey + 10)))
