def _v91_draco_apply_rupture(self, now):
    if self.damage_applied or not self.target_valid():
        return
    self.damage_applied = True
    target = self.target
    center = v90_actor_center(target)
    source = V90MagicSource(
        oyuncu_x, oyuncu_y, "draco_calcinans"
    )
    damage = max(
        92,
        int(
            round(
                104
                + float(oyuncu_guc) * 2.65
                + float(oyuncu_level) * 1.85
            )
        ),
    )
    target.hasar_al(damage, source)
    v90_draco_stats["ruptures"] += 1
    v90_spawn_embers(
        center,
        36,
        self.seed ^ int(now),
        pygame.Vector2(0.0, -28.0),
    )
    for index, offset in enumerate(
        ((-8, 5), (8, 6), (0, 12))
    ):
        v90_spawn_ash(
            center + pygame.Vector2(offset),
            now,
            self.seed ^ int(now) ^ (index * 7919),
        )
    kamera_hit_sarsintisi_baslat(
        15.0 if az_hareket else 21.0, 420
    )
    if v90_actor_alive(target):
        uid = v84_actor_uid(target)
        v90_calcinatio[uid] = V90CalcinatioStatus(
            target,
            uid,
            int(now),
            int(now) + V90_CALCINATIO_DURATION_MS,
            int(now) + V90_CALCINATIO_TICK_MS,
            int(now)
            + V90_CALCINATIO_PHYSICAL_TRIGGER_MS,
            v90_actor_center(target),
            int(now) + 70,
            self.seed ^ int(now),
        )
        for attr in (
            "hit_stun_until",
            "recovery_until",
            "stagger_until",
        ):
            if hasattr(target, attr):
                setattr(
                    target,
                    attr,
                    max(
                        int(getattr(target, attr, 0)),
                        int(now) + 620,
                    ),
                )
