    w, h = max(1, int(target_size[0])), max(1, int(target_size[1]))
    canvas = pygame.Surface((w, h), pygame.SRCALPHA)
    scale = min((w * 0.70) / max(1, image.get_width()), (h * 0.70) / max(1, image.get_height()))
    new_size = (
        max(1, int(round(image.get_width() * scale))),
        max(1, int(round(image.get_height() * scale))),
    )
    small = pygame.transform.scale(image, new_size)
    canvas.blit(small, small.get_rect(center=canvas.get_rect().center))
    return canvas
