def gelistirici_test_girdisi_uygula(olay):
    global v94_test_panel_visible, oyuncu_altin
    if olay.type != pygame.KEYDOWN:
        return _v94_dev_previous(olay)
    ctrl = bool(olay.mod & pygame.KMOD_CTRL)
    quote_keys = {pygame.K_QUOTE}
    quotedbl = getattr(pygame, "K_QUOTEDBL", None)
    if quotedbl is not None:
        quote_keys.add(quotedbl)
    if ctrl and olay.key in quote_keys:
        v94_test_panel_visible = not v94_test_panel_visible
        return True
    if ctrl and olay.key == pygame.K_1:
        return _v94_bind_test_spell("fire_magic")
    if ctrl and olay.key == pygame.K_2:
        return _v94_bind_test_spell("draco_calcinans")

    return _v94_dev_previous(olay)


