def _v98_ground_fire_draw(self):
    frames = V98_UNIVERSAL_FIRE_FRAMES or FIRE_MAGIC_GROUND_SPRITELERI
    if not getattr(self, "active", False) or not frames:
        return

    now = pygame.time.get_ticks()
    duration = max(1, int(getattr(self, "duration_ms", 1)))
    progress = max(0.0, min(1.0, (now - int(self.start_ms)) / float(duration)))
    fade_in = min(1.0, progress / 0.07)
    fade_out = 1.0 if progress < 0.70 else max(0.0, (1.0 - progress) / 0.30)
    alpha = int(round(255 * fade_in * fade_out))
    if alpha <= 0:
        return


    sequence = (0, 1, 2, 1) if len(frames) >= 3 else tuple(range(len(frames)))
    phase = (now // 96 + int(getattr(self, "v89_pulse_phase", 0))) % len(sequence)
    frame = frames[sequence[phase] % len(frames)]

    scale_value = max(0.62, min(1.42, float(getattr(self, "scale", 1.0))))
    target_h = int(round(29.0 * scale_value * KAMERA_YAKINLASTIRMA))
    image = _v98_fire_frame_image(frame, target_h, alpha)
    if image is None:
        return

    sx = int(round(dunya_ekran_x(self.x)))
    sy = int(round(dunya_ekran_y(self.y) + 3))


    glow_w = max(12, int(round(target_h * 1.20)))
    glow_h = max(5, int(round(target_h * 0.30)))
    glow = pygame.Surface((glow_w, glow_h), pygame.SRCALPHA)
    pygame.draw.ellipse(glow, (255, 104, 10, int(alpha * 0.18)), glow.get_rect())
    ekran.blit(glow, glow.get_rect(center=(sx, sy - 2)), special_flags=pygame.BLEND_RGBA_ADD)
    ekran.blit(image, image.get_rect(midbottom=(sx, sy)))
