    age = max(0, now - self.anim_epoch)
    idx = 0 if age < 46 else 1 if age < 96 else min(2, len(FIRE_MAGIC_PROJECTILE_SPRITELERI) - 1)
    frame = FIRE_MAGIC_PROJECTILE_SPRITELERI[idx]
    direction_name = (
        "left" if self.direction.x < -0.5 else
        "right" if self.direction.x > 0.5 else
        "up" if self.direction.y < 0.0 else "down"
    )
    temp_ratio = v39_clamp01(
        (self.temperature_k - V38_FIRE_MIN_VISIBLE_TEMPERATURE_K)
        / max(1.0, V38_FIRE_CORE_TEMPERATURE_K - V38_FIRE_MIN_VISIBLE_TEMPERATURE_K)
    )
    height = int(round(
        62
        * FIRE_MAGIC_PROJECTILE_VISUAL_SCALE
        * (0.95 + temp_ratio * 0.08)
        * KAMERA_YAKINLASTIRMA
    ))
    body = _v38_oriented_fire_sprite(frame, height, direction_name, 255)
    rect = body.get_rect(center=(sx, sy))
