def v106_corona_frames_load(force_resolve=False):
    global corona_aetherica_cast_yolu, v107_corona_asset_path
    if force_resolve or not corona_aetherica_cast_yolu or not os.path.isfile(corona_aetherica_cast_yolu):
        corona_aetherica_cast_yolu = mevcut_ilk_dosya(CORONA_AETHERICA_CAST_ADAYLARI)
    path = corona_aetherica_cast_yolu
    v107_corona_asset_path = str(path or "")
    if not path or not os.path.isfile(path):
        return []
    try:
        sheet = pygame.image.load(path).convert_alpha()
    except (pygame.error, OSError):
        return []



    reference = (503.0, 219.0)
    rects = (
        (66.0, 1.0, 70.0, 70.0),
        (139.0, 1.0, 70.0, 70.0),
        (212.0, 1.0, 70.0, 70.0),
        (285.0, 1.0, 70.0, 70.0),
    )
    frames = []
    for rx, ry, rw, rh in rects:
        x = int(round(rx / reference[0] * sheet.get_width()))
        y = int(round(ry / reference[1] * sheet.get_height()))
        w = max(1, int(round(rw / reference[0] * sheet.get_width())))
        h = max(1, int(round(rh / reference[1] * sheet.get_height())))
        area = pygame.Rect(x, y, w, h).clip(sheet.get_rect())
        if area.width <= 0 or area.height <= 0:
            continue
        frame = sheet.subsurface(area).copy().convert_alpha()


        for px in range(frame.get_width()):
            for py in range(frame.get_height()):
                c = frame.get_at((px, py))
                near_black = max(c.r, c.g, c.b) <= 18
                preview_blue = (
                    abs(int(c.r) - 85) <= 14
                    and abs(int(c.g) - 149) <= 16
                    and abs(int(c.b) - 188) <= 18
                )
                if c.a <= 2 or near_black or preview_blue:
                    frame.set_at((px, py), (0, 0, 0, 0))
        bounds = frame.get_bounding_rect(min_alpha=4)
        if bounds.width > 0 and bounds.height > 0:
            frames.append(frame.subsurface(bounds).copy().convert_alpha())
    return frames
