def corona_aetherica_kullan():
    global oyuncu_mana, v106_corona_last_cast_ms, v107_corona_test_cast_ready
    now = pygame.time.get_ticks()
    if oyun_durumu != OYUN or oyun_alt_durumu != HARITA or oyuncu_hp <= 0:
        return False


    if oyun_sinematik_kilitli_mi():
        return False
    if v106_corona_active_orbs():
        bildirim_goster(bt("Corona hâlâ yörüngede.", "Corona is still in orbit."))
        return False

    debug_cast = bool(GELISTIRICI_MODU and v107_corona_test_cast_ready)
    remaining = V106_CORONA_COOLDOWN_MS - (int(now) - int(v106_corona_last_cast_ms))
    if remaining > 0 and not debug_cast:
        bildirim_goster(f"Corona Aetherica: {remaining / 1000.0:.1f}s")
        return False
    if float(oyuncu_mana) < float(V106_CORONA_MANA_COST) and not debug_cast:
        hud_uyari_baslat("mana")
        bildirim_goster(
            bt(
                f"Corona Aetherica için {V106_CORONA_MANA_COST} mana gerekli.",
                f"Corona Aetherica requires {V106_CORONA_MANA_COST} mana.",
            )
        )
        return False



    v107_corona_asset_ensure_loaded()

    if not debug_cast:
        oyuncu_mana = max(0.0, float(oyuncu_mana) - float(V106_CORONA_MANA_COST))
    else:
        v107_corona_test_cast_ready = False

    v106_corona_last_cast_ms = int(now)
    v106_corona.active = True
    v106_corona.started_ms = int(now)
    v106_corona.expires_ms = int(now) + V106_CORONA_ORBIT_MS
    v106_corona.cores = [0, 1, 2]
    v106_corona.projectiles.clear()
    v106_corona.impacts.clear()
    v106_corona.contact_next.clear()
    v106_corona.seed = int(now) ^ int(oyuncu_x * 59) ^ int(oyuncu_y * 83)
    oyuncu_saldiri_durumunu_sifirla()
    dunya_olayi_kaydet(
        "spell_cast",
        spell="corona_aetherica",
        debug_free=bool(debug_cast),
        authored_frames=len(V106_CORONA_FRAMES),
    )
    return True
