def v110_fulmen_source(x, y):
    source = V90MagicSource(x, y, "fulmen_caeruleum")
    source.tur = "fulmen_caeruleum"
    source.blood_profile = "magic_heavy"
    return source



def v110_fulmen_actor_kind(actor):
    if actor in (tarkard_actor, torrmund_actor) or bool(getattr(actor, "boss", False)):
        return "boss"
    if bool(getattr(actor, "elite", False)) or bool(getattr(actor, "special", False)):
        return "elite"
    if actor in common_enemies:
        return "common"
    return "elite"
