def v110_fulmen_prepare(target_actor, target_point, self_strike=False):
    v110_fulmen.active = True
    v110_fulmen.phase = "guide"
    v110_fulmen.phase_started_ms = pygame.time.get_ticks()
    v110_fulmen.started_ms = v110_fulmen.phase_started_ms
    v110_fulmen.strike_ms = 0
    v110_fulmen.target_actor = target_actor
    v110_fulmen.target_uid = v84_actor_uid(target_actor)
    v110_fulmen.target_point = pygame.Vector2(target_point)
    v110_fulmen.start_point = pygame.Vector2(float(oyuncu_x), float(oyuncu_y) - 36.0)
    v110_fulmen.seed = (
        int(v110_fulmen.phase_started_ms)
        ^ int(v110_fulmen.target_point.x * 31.0)
        ^ int(v110_fulmen.target_point.y * 17.0)
    )
    v110_fulmen.main_points = v110_polyline_points(
        v110_fulmen.start_point,
        v110_fulmen.target_point,
        jitter=18.0,
        segments=8,
        seed=v110_fulmen.seed,
    )
    v110_fulmen.branches = v110_build_branches(v110_fulmen.main_points, v110_fulmen.seed)
    v110_fulmen.chain_points = []
    v110_fulmen.chain_targets = []
    v110_fulmen.resolved = False
    v110_fulmen.self_strike = bool(self_strike)



def v110_fulmen_queue_cast():
    actor, point = v110_fulmen_pick_target()
    if point is None:
        player = pygame.Vector2(float(oyuncu_x), float(oyuncu_y) - 24.0)
        facing = v110_fulmen_facing()
        normal = pygame.Vector2(-facing.y, facing.x)
        distance = random.uniform(240.0, 410.0)
        point = player + facing * distance + normal * random.uniform(-70.0, 70.0)
        self_strike = random.random() < 0.24
        if self_strike:
            point = pygame.Vector2(float(oyuncu_x), float(oyuncu_y) - 30.0)
        v110_fulmen_prepare(None, point, self_strike=self_strike)
    else:
        v110_fulmen_prepare(actor, point, self_strike=False)
