# <POTBO_STAGE S2619>



def v110_chain_lightning(center, primary_actor):
    center = pygame.Vector2(center)
    chains = []
    hit = []
    for actor in v90_hostiles():
        if actor is primary_actor or not v90_actor_alive(actor):
            continue
        actor_center = v90_actor_center(actor)
        distance = center.distance_to(actor_center)
        if distance <= 12.0 or distance > V110_FULMEN_CHAIN_RADIUS:
            continue
        chains.append(
            v110_polyline_points(
                center,
                actor_center,
                jitter=8.0,
                segments=5,
                seed=v110_fulmen.seed ^ int(distance * 11.0) ^ int(actor_center.x),
            )
        )
        hit.append(actor)
    v110_fulmen.chain_points = chains
    v110_fulmen.chain_targets = hit
    source = v110_fulmen_source(center.x, center.y)
    for actor in hit:
        kind = v110_fulmen_actor_kind(actor)
        if kind == "boss":
            damage = max(42, int(round(68 + float(oyuncu_guc) * 0.7 + float(oyuncu_level) * 1.2)))
            stun = 520
        else:
            damage = max(55, int(round(82 + float(oyuncu_guc) * 0.9 + float(oyuncu_level) * 1.7)))
            stun = 840
        actor.hasar_al(int(damage), source)
        v110_apply_stun(actor, stun)



def v110_resolve_fulmen_strike():
    if v110_fulmen.resolved:
        return
    v110_fulmen.resolved = True
    now = pygame.time.get_ticks()
    v110_fulmen.strike_ms = int(now)
    kamera_hit_sarsintisi_baslat(12.0 if az_hareket else 19.0, 260)
    center = pygame.Vector2(v110_fulmen.target_point)
    source = v110_fulmen_source(center.x, center.y)
    actor = v110_fulmen.target_actor if v90_actor_alive(v110_fulmen.target_actor) else None
    if actor is not None:
        center = v90_actor_center(actor)
        v110_fulmen.target_point = center
        kind = v110_fulmen_actor_kind(actor)
        if kind == "common":
            damage = max(
                int(getattr(actor, "hp", 0)) + 9999,
                280,
            )
            actor.hasar_al(int(damage), source)
        elif kind == "boss":
            damage = max(108, int(round(128 + float(oyuncu_guc) * 1.4 + float(oyuncu_level) * 2.3)))
            actor.hasar_al(int(damage), source)
            v110_apply_stun(actor, 760)
        else:
            damage = max(180, int(round(214 + float(oyuncu_guc) * 2.3 + float(oyuncu_level) * 2.9)))
            actor.hasar_al(int(damage), source)
            v110_apply_stun(actor, 1100)
        v110_chain_lightning(center, actor)
    elif v110_fulmen.self_strike:
        self_damage = max(28.0, float(oyuncu_max_hp) * 0.45)
        globals()["oyuncu_hp"] = max(1.0, float(oyuncu_hp) - self_damage)
        globals()["oyuncu_stamina"] = 0.0
        hud_uyari_baslat("health")
    else:
        v110_fulmen.chain_points = []
        v110_fulmen.chain_targets = []



def fulmen_caeruleum_kullan():
    global oyuncu_mana, v110_fulmen_last_cast_ms
    now = pygame.time.get_ticks()
    if oyun_durumu != OYUN or oyun_alt_durumu != HARITA or oyuncu_hp <= 0:
        return False
    if oyun_sinematik_kilitli_mi():
        return False
    if v110_fulmen.active:
        return False
    dev_free = bool(v108_dev_spell_unlimited("fulmen_caeruleum"))
    remaining = V110_FULMEN_COOLDOWN_MS - (int(now) - int(v110_fulmen_last_cast_ms))
    if remaining > 0 and not dev_free:
        bildirim_goster(f"Fulmen Caeruleum: {remaining / 1000.0:.1f}s")
        return False
    if float(oyuncu_mana) < float(V110_FULMEN_MANA_COST) and not dev_free:
        hud_uyari_baslat("mana")
        bildirim_goster(
            bt(
                f"Fulmen Caeruleum için {V110_FULMEN_MANA_COST} mana gerekli.",
                f"Fulmen Caeruleum requires {V110_FULMEN_MANA_COST} mana.",
            )
        )
        return False
    if not dev_free:
        oyuncu_mana = max(0.0, float(oyuncu_mana) - float(V110_FULMEN_MANA_COST))
    v110_fulmen_last_cast_ms = int(now)
    v110_fulmen_queue_cast()
    dunya_olayi_kaydet(
        "spell_cast",
        spell="fulmen_caeruleum",
        debug_free=bool(dev_free),
    )
    return True
