def q_hizli_itemi_kullan():
    q_hizli_slot_normalize_et()
    if isinstance(q_hizli_item_index, int) and 0 <= q_hizli_item_index < len(envanter_itemleri):
        item = envanter_itemleri[q_hizli_item_index]
        if isinstance(item, dict) and item.get("id") == "fulmen_caeruleum":
            return fulmen_caeruleum_kullan()
    return _v110_q_use_raw()



def v110_fulmen_update(now=None):
    if now is None:
        now = pygame.time.get_ticks()
    if not v110_fulmen.active:
        return
    if oyun_durumu != OYUN or oyun_alt_durumu != HARITA or oyuncu_hp <= 0:
        v110_fulmen.reset()
        return
    elapsed = int(now) - int(v110_fulmen.phase_started_ms)
    if v110_fulmen.phase == "guide" and elapsed >= V110_FULMEN_GUIDE_MS:
        v110_fulmen.phase = "ion"
        v110_fulmen.phase_started_ms = int(now)
    elif v110_fulmen.phase == "ion" and elapsed >= V110_FULMEN_ION_MS:
        v110_fulmen.phase = "strike"
        v110_fulmen.phase_started_ms = int(now)
        v110_resolve_fulmen_strike()
    elif v110_fulmen.phase == "strike" and elapsed >= V110_FULMEN_STRIKE_MS:
        v110_fulmen.phase = "after"
        v110_fulmen.phase_started_ms = int(now)
    elif v110_fulmen.phase == "after" and elapsed >= V110_FULMEN_AFTER_MS:
        v110_fulmen.reset()
