def v110_draw_impact_sprite(center, age_ms):
    pos = v110_screen_point((center.x, center.y - 16.0))
    if V110_FULMEN_ELECTRIC_IMAGE is not None:
        src = V110_FULMEN_ELECTRIC_IMAGE
    else:
        src = V110_FULMEN_CAST_IMAGE
    if src is None:
        radius = max(6, int(24 - age_ms * 0.12))
        pygame.draw.circle(ekran, (255, 255, 255), pos, radius, 1)
        return
    bucket = max(0, min(255, int(255 - age_ms * 1.6)))
    key = (id(src), bucket)
    draw = v110_fulmen_effect_cache.get(key)
    if draw is None:
        draw = src.copy().convert_alpha()
        draw.fill((255, 255, 255), special_flags=pygame.BLEND_RGB_MAX)
        draw.set_alpha(bucket)
        if len(v110_fulmen_effect_cache) >= 48:
            for old in list(v110_fulmen_effect_cache)[:12]:
                v110_fulmen_effect_cache.pop(old, None)
        v110_fulmen_effect_cache[key] = draw
    rect = draw.get_rect(center=pos)
    ekran.blit(draw, rect)



def v110_fulmen_draw(now=None):
    if now is None:
        now = pygame.time.get_ticks()
    if not v110_fulmen.active:
        return
    main = v110_fulmen.main_points
    if len(main) < 2:
        return
    phase = v110_fulmen.phase
    if phase == "guide":
        v110_draw_polyline(main, (74, 132, 255), 2)
        v110_draw_polyline(main, (158, 198, 255), 1)
    elif phase == "ion":
        v110_draw_polyline(main, (96, 154, 255), 2)
        v110_draw_polyline(main, (234, 242, 255), 1)
        age = max(1, int(now) - int(v110_fulmen.phase_started_ms))
        step = max(10, 42 - age // 3)
        for index, point in enumerate(main[:-1]):
            nxt = pygame.Vector2(main[index + 1])
            seg = nxt - pygame.Vector2(point)
            length = seg.length()
            if length <= 1e-6:
                continue
            direction = seg.normalize()
            for offset in range(0, int(length), step):
                p = pygame.Vector2(point) + direction * float(offset)
                sx, sy = v110_screen_point((p.x, p.y))
                pygame.draw.circle(ekran, (255, 255, 255), (sx, sy), 1)
    else:
        age = max(0, int(now) - int(v110_fulmen.strike_ms or now))
        width = 4 if phase == "strike" else 3
        v110_draw_polyline(main, (170, 205, 255), width + 2)
        v110_draw_polyline(main, (255, 255, 255), width)
