def v111_fulmen_light_sprite(src, alpha=255, scale=1.0):
    if src is None:
        return None
    alpha_bucket = max(0, min(255, int(alpha // 8) * 8))
    scale_bucket = max(0.20, min(3.0, round(float(scale), 2)))
    key = (id(src), alpha_bucket, scale_bucket)
    cached = V111_FULMEN_LIGHT_CACHE.get(key)
    if cached is not None:
        return cached
    img = src.copy().convert_alpha()
    if scale_bucket != 1.0:
        w = max(2, int(round(img.get_width() * scale_bucket)))
        h = max(2, int(round(img.get_height() * scale_bucket)))
        img = pygame.transform.smoothscale(img, (w, h)).convert_alpha()
    img.fill((255, 255, 255), special_flags=pygame.BLEND_RGB_MAX)
    inner = pygame.Surface(img.get_size(), pygame.SRCALPHA).convert_alpha()
    inner.fill((255, 255, 255, min(255, alpha_bucket)))
    alpha_clip = pygame.mask.from_surface(img, 2).to_surface(
        setcolor=(255, 255, 255, 255),
        unsetcolor=(0, 0, 0, 0),
    ).convert_alpha()
    inner.blit(alpha_clip, (0, 0), special_flags=pygame.BLEND_RGBA_MULT)
    img.blit(inner, (0, 0), special_flags=pygame.BLEND_RGBA_ADD)
    img.set_alpha(alpha_bucket)
    if len(V111_FULMEN_LIGHT_CACHE) >= 72:
        for old in list(V111_FULMEN_LIGHT_CACHE)[:18]:
            V111_FULMEN_LIGHT_CACHE.pop(old, None)
    V111_FULMEN_LIGHT_CACHE[key] = img
    return img


def v111_fulmen_ground_paths(center, seed=0):
    center = pygame.Vector2(center)
    rng = random.Random(int(seed) ^ 0xF11A)
    result = []
    count = rng.randint(5, 7)
    base_angles = [
        -0.15,
        0.35,
        0.95,
        1.75,
        2.65,
        3.55,
        4.45,
    ]
    for i in range(count):
        angle = base_angles[i % len(base_angles)] + rng.uniform(-0.22, 0.22)
        length = rng.uniform(46.0, 118.0)
        flatten = rng.uniform(0.16, 0.34)
        endpoint = pygame.Vector2(
            center.x + math.cos(angle) * length,
            center.y + math.sin(angle) * length * flatten,
        )
        path = v110_polyline_points(
            center,
            endpoint,
            jitter=8.0,
            segments=rng.randint(4, 6),
            seed=rng.randint(0, 10**6),
        )
        result.append(path)
    return result


