def v110_fulmen_draw(now=None):
    if now is None:
        now = pygame.time.get_ticks()
    if not v110_fulmen.active:
        return
    main = v110_fulmen.main_points
    if len(main) < 2:
        return
    phase = v110_fulmen.phase
    if phase == "guide":
        v110_draw_polyline(main, (72, 131, 255), 2)
        v110_draw_polyline(main, (215, 231, 255), 1)
        return
    if phase == "ion":
        v110_draw_polyline(main, (102, 162, 255), 2)
        v110_draw_polyline(main, (255, 255, 255), 1)
        age = max(1, int(now) - int(v110_fulmen.phase_started_ms))
        step = max(8, 28 - age // 4)
        for index, point in enumerate(main[:-1]):
            nxt = pygame.Vector2(main[index + 1])
            seg = nxt - pygame.Vector2(point)
            length = seg.length()
            if length <= 1e-6:
                continue
            direction = seg.normalize()
            for offset in range(0, int(length), step):
                p = pygame.Vector2(point) + direction * float(offset)
                sx, sy = v110_screen_point((p.x, p.y))
                pygame.draw.circle(ekran, (255, 255, 255), (sx, sy), 1)
        return

    age = max(0, int(now) - int(v110_fulmen.strike_ms or now))
    bolt_w = 5 if phase == "strike" else 4
    v110_draw_polyline(main, (158, 200, 255), bolt_w + 2)
    v110_draw_polyline(main, (255, 255, 255), bolt_w)
    for branch in v110_fulmen.branches:
        v110_draw_polyline(branch, (205, 225, 255), max(1, bolt_w - 2))
        v110_draw_polyline(branch, (255, 255, 255), 1)
    v110_draw_impact_sprite(v110_fulmen.target_point, age)
    v111_draw_ground_electric(v110_fulmen.target_point, age)

    for chain in v110_fulmen.chain_points:
        v110_draw_polyline(chain, (158, 197, 255), 2)
        v110_draw_polyline(chain, (255, 255, 255), 1)
