def v115_update_scars(now=None):
    if now is None:
        now = pygame.time.get_ticks()
    alive = []
    dt = 16.0 / 1000.0
    for scar in v115_fulmen_scars:
        if now >= int(scar.get("expire", 0)):
            continue
        embers = []
        for ember in scar.get("embers", []):
            age = float(ember.get("age", 0)) + 16.0
            if age >= float(ember.get("life", 0)):
                continue
            ember["age"] = age
            ember["x"] += float(ember.get("vx", 0.0)) * dt
            ember["y"] += float(ember.get("vy", 0.0)) * dt
            ember["vy"] += 14.0 * dt
            embers.append(ember)
        scar["embers"] = embers
        alive.append(scar)
    v115_fulmen_scars[:] = alive[-8:]



def v115_draw_scars():
    if not v115_fulmen_scars:
        return
    now = pygame.time.get_ticks()
    for scar in v115_fulmen_scars:
        fade = max(0.0, min(1.0, (int(scar.get("expire", 0)) - now) / float(V115_FULMEN_SCORCH_LIFETIME_MS)))
        if fade <= 0.0:
            continue
        center = scar["center"]
        layer = pygame.Surface((GENISLIK, YUKSEKLIK), pygame.SRCALPHA).convert_alpha()

        for blot in scar.get("blots", []):
            sx, sy = v110_screen_point((center.x + blot["ox"], center.y + blot["oy"]))
            rx = max(2, int(round(blot["rx"])))
            ry = max(1, int(round(blot["ry"])))
            pygame.draw.ellipse(
                layer,
                (8, 8, 8, int(blot["a"] * fade)),
                (sx - rx, sy - ry, rx * 2, ry * 2),
            )
        for crack in scar.get("cracks", []):
            pts = [v110_screen_point((p.x, p.y)) for p in crack]
            if len(pts) >= 2:
                pygame.draw.lines(layer, (10, 10, 10, int(120 * fade)), False, pts, 2)
                pygame.draw.lines(layer, (34, 18, 8, int(52 * fade)), False, pts, 1)
        ekran.blit(layer, (0, 0))

        for ember in scar.get("embers", []):
            t = max(0.0, 1.0 - float(ember.get("age", 0.0)) / max(1.0, float(ember.get("life", 1.0))))
            if t <= 0.0:
                continue
            sx, sy = v110_screen_point((ember["x"], ember["y"]))
            r = max(1, int(round(float(ember.get("r", 1.0)) * (0.65 + 0.35 * t))))
            alpha = max(0, min(255, int(180 * t)))
            glow = pygame.Surface((r * 6, r * 6), pygame.SRCALPHA).convert_alpha()
            pygame.draw.circle(glow, (255, 170, 62, alpha // 3), (r * 3, r * 3), r * 2)
            pygame.draw.circle(glow, (255, 224, 150, alpha), (r * 3, r * 3), r)
            ekran.blit(glow, glow.get_rect(center=(sx, sy)), special_flags=pygame.BLEND_RGBA_ADD)
