            ember["age"] = age
            drift = float(ember.get("drift", 1.0))

            ember["x"] += (float(ember.get("vx", 0.0)) + math.sin(age * 0.011 * drift) * 6.0) * dt
            ember["y"] += float(ember.get("vy", 0.0)) * dt
            ember["vy"] += 10.0 * dt
            ember["vx"] *= 0.996
            embers.append(ember)
