V117_VERSION = "117.0"
V117_FULMEN_OFFSCREEN_TOP = 220.0
V117_FULMEN_OFFSCREEN_JITTER_X = 34.0
V117_FULMEN_OFFSCREEN_JITTER_Y = 40.0




def v110_fulmen_pick_target():
    player = pygame.Vector2(float(oyuncu_x), float(oyuncu_y) - 26.0)
    facing = v110_fulmen_facing()
    best_actor = None
    best_center = None
    best_score = float("inf")
    for actor in v90_hostiles():
        center = v90_actor_center(actor)
        delta = center - player
        dist = delta.length()
        if dist <= 6.0 or dist > V110_FULMEN_RANGE:
            continue
        direction = delta.normalize()
        if facing.dot(direction) < V110_FULMEN_CONE_DOT:
            continue
        lateral = abs(delta.x * facing.y - delta.y * facing.x)
        if lateral > 150.0:
            continue
        score = dist + lateral * 0.25
        if score < best_score:
            best_score = score
            best_actor = actor
            best_center = center
    return best_actor, best_center



_v117_prepare_raw = v110_fulmen_prepare

def v110_fulmen_prepare(target_actor, target_point, self_strike=False):
    _v117_prepare_raw(target_actor, target_point, self_strike=self_strike)
    rng = random.Random(int(v110_fulmen.seed) ^ 0x1170)
    visible_top_world = float(kamera_y)
    start = pygame.Vector2(v110_fulmen.target_point)
    start.x += rng.uniform(-V117_FULMEN_OFFSCREEN_JITTER_X, V117_FULMEN_OFFSCREEN_JITTER_X)
    start.y = visible_top_world - (V117_FULMEN_OFFSCREEN_TOP + rng.uniform(0.0, V117_FULMEN_OFFSCREEN_JITTER_Y)) / max(0.01, KAMERA_YAKINLASTIRMA)
    v110_fulmen.start_point = start
    v110_fulmen.main_points = v110_polyline_points(
        v110_fulmen.start_point,
        v110_fulmen.target_point,
        jitter=22.0,
        segments=10,
        seed=v110_fulmen.seed,
    )
    v110_fulmen.branches = v110_build_branches(v110_fulmen.main_points, v110_fulmen.seed)

    extra = []
    rng2 = random.Random(int(v110_fulmen.seed) ^ 0x17AC)
    for _ in range(3):
        if len(v110_fulmen.main_points) < 3:
            break
        idx = rng2.randint(1, len(v110_fulmen.main_points) - 2)
        root = pygame.Vector2(v110_fulmen.main_points[idx])
        angle = rng2.uniform(-2.5, 2.5)
        length = rng2.uniform(36.0, 68.0)
        tip = root + pygame.Vector2(math.cos(angle) * length, math.sin(angle) * length)
        extra.append(v110_polyline_points(root, tip, jitter=8.0, segments=4, seed=rng2.randint(0, 10**6)))
    v110_fulmen.branches.extend(extra)
    v110_fulmen.ground_paths = []
    v110_fulmen.impact_paths = []
